screenPanels.initJs:
function(container, apiUrl, tables) {
  let salesChart, orderChart, weatherChart;
  let currentStoreId = '';
  let currentPeriod = 30;

  // テーブルインデックスの定義
  const TABLE_STORES = 1;
  const TABLE_PRODUCTS = 2;
  const TABLE_SALES = 3;
  const TABLE_WEATHER = 4;
  const TABLE_EVENTS = 5;
  const TABLE_PREDICTIONS = 7;
  const TABLE_ORDERS = 8;

  // 店舗選択の初期化
  function initStoreSelect() {
    const storeSelect = container.querySelector('#store-select');
    const stores = tables[TABLE_STORES]?.records || [];

    stores.forEach(store => {
      if (store.有効フラグ) {
        const option = document.createElement('option');
        option.value = store.店舗ID;
        option.textContent = store.店舗名;
        storeSelect.appendChild(option);
      }
    });
  }

  // KPI計算と表示
  function updateKPIs() {
    const salesData = tables[TABLE_SALES]?.records || [];
    const ordersData = tables[TABLE_ORDERS]?.records || [];
    const predictionsData = tables[TABLE_PREDICTIONS]?.records || [];

    const now = new Date();
    const currentMonth = now.getFullYear() + '-' + String(now.getMonth() + 1).padStart(2, '0');
    const lastMonth = now.getFullYear() + '-' + String(now.getMonth()).padStart(2, '0');

    // 今月の売上実績
    const currentSales = salesData
      .filter(s => s.売上日?.startsWith(currentMonth) && (!currentStoreId || s.店舗ID === currentStoreId))
      .reduce((sum, s) => sum + (s.売上金額 || 0), 0);

    const lastSales = salesData
      .filter(s => s.売上日?.startsWith(lastMonth) && (!currentStoreId || s.店舗ID === currentStoreId))
      .reduce((sum, s) => sum + (s.売上金額 || 0), 0);

    const salesChange = lastSales > 0 ? ((currentSales - lastSales) / lastSales * 100).toFixed(1) : 0;

    container.querySelector('#sales-amount').textContent = `¥${currentSales.toLocaleString()}`;
    container.querySelector('#sales-change').textContent = `前月比 ${salesChange > 0 ? '+' : ''}${salesChange}%`;

    // 需要予測精度
    const accuracyData = predictionsData.filter(p => p.実績数量 && p.予測数量);
    let avgAccuracy = 0;
    if (accuracyData.length > 0) {
      const totalAccuracy = accuracyData.reduce((sum, p) => {
        const accuracy = 100 - Math.abs(p.実績数量 - p.予測数量) / p.実績数量 * 100;
        return sum + Math.max(0, accuracy);
      }, 0);
      avgAccuracy = (totalAccuracy / accuracyData.length).toFixed(1);
    }

    container.querySelector('#prediction-accuracy').textContent = `${avgAccuracy}%`;

    // 発注件数
    const orderCount = ordersData.filter(o => !currentStoreId || o.店舗ID === currentStoreId).length;
    const processingCount = ordersData.filter(o => 
      (!currentStoreId || o.店舗ID === currentStoreId) && 
      o.発注ステータス === '発注済'
    ).length;

    container.querySelector('#order-count').textContent = `${orderCount}件`;
    container.querySelector('#order-status').textContent = `処理中: ${processingCount}件`;

    // 在庫アラート（仮想的な計算）
    const alertCount = Math.floor(Math.random() * 5) + 1;
    container.querySelector('#alert-count').textContent = `${alertCount}件`;
  }

  // 売上トレンドグラフ
  function renderSalesTrend() {
    const ctx = container.querySelector('#sales-trend-chart').getContext('2d');
    const salesData = tables[TABLE_SALES]?.records || [];

    const endDate = new Date();
    const startDate = new Date();
    startDate.setDate(endDate.getDate() - currentPeriod);

    const dailySales = {};
    for (let d = new Date(startDate); d <= endDate; d.setDate(d.getDate() + 1)) {
      const dateStr = d.toISOString().split('T')[0];
      dailySales[dateStr] = 0;
    }

    salesData
      .filter(s => {
        const saleDate = s.売上日?.split('T')[0];
        return saleDate >= startDate.toISOString().split('T')[0] && 
               saleDate <= endDate.toISOString().split('T')[0] &&
               (!currentStoreId || s.店舗ID === currentStoreId);
      })
      .forEach(s => {
        const dateStr = s.売上日?.split('T')[0];
        if (dailySales.hasOwnProperty(dateStr)) {
          dailySales[dateStr] += s.売上金額 || 0;
        }
      });

    if (salesChart) salesChart.destroy();

    salesChart = new Chart(ctx, {
      type: 'line',
      data: {
        labels: Object.keys(dailySales).map(d => new Date(d).toLocaleDateString()),
        datasets: [{
          label: '売上金額',
          data: Object.values(dailySales),
          borderColor: '#4f46e5',
          backgroundColor: 'rgba(79, 70, 229, 0.1)',
          tension: 0.4
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          y: {
            beginAtZero: true,
            ticks: {
              callback: function(value) {
                return '¥' + value.toLocaleString();
              }
            }
          }
        }
      }
    });
  }

  // 商品別売上ランキング
  function renderProductRanking() {
    const salesData = tables[TABLE_SALES]?.records || [];
    const productsData = tables[TABLE_PRODUCTS]?.records || [];

    const productSales = {};
    salesData
      .filter(s => !currentStoreId || s.店舗ID === currentStoreId)
      .forEach(s => {
        if (!productSales[s.商品ID]) {
          productSales[s.商品ID] = 0;
        }
        productSales[s.商品ID] += s.売上金額 || 0;
      });

    const ranking = Object.entries(productSales)
      .sort(([,a], [,b]) => b - a)
      .slice(0, 10)
      .map(([productId, amount], index) => {
        const product = productsData.find(p => p.商品ID === productId);
        return {
          rank: index + 1,
          name: product?.商品名 || '不明な商品',
          amount: amount
        };
      });

    const rankingHtml = ranking.length > 0 ? 
      ranking.map(item => `
        <div class="ranking-item">
          <span class="ranking-rank">${item.rank}</span>
          <span class="ranking-name">${item.name}</span>
          <span class="ranking-amount">¥${item.amount.toLocaleString()}</span>
        </div>
      `).join('') :
      '<div class="loading">データがありません</div>';

    container.querySelector('#product-ranking').innerHTML = rankingHtml;
  }

  // 発注状況チャート
  function renderOrderStatus() {
    const ctx = container.querySelector('#order-status-chart').getContext('2d');
    const ordersData = tables[TABLE_ORDERS]?.records || [];

    const statusCount = {};
    ordersData
      .filter(o => !currentStoreId || o.店舗ID === currentStoreId)
      .forEach(o => {
        const status = o.発注ステータス || '不明';
        statusCount[status] = (statusCount[status] || 0) + 1;
      });

    if (orderChart) orderChart.destroy();

    orderChart = new Chart(ctx, {
      type: 'doughnut',
      data: {
        labels: Object.keys(statusCount),
        datasets: [{
          data: Object.values(statusCount),
          backgroundColor: [
            '#4f46e5',
            '#06b6d4',
            '#10b981',
            '#f59e0b',
            '#ef4444'
          ]
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false
      }
    });
  }

  // 天候影響分析チャート
  function renderWeatherImpact() {
    const ctx = container.querySelector('#weather-impact-chart').getContext('2d');
    const weatherData = tables[TABLE_WEATHER]?.records || [];
    const salesData = tables[TABLE_SALES]?.records || [];

    const weatherSales = {};
    weatherData.forEach(w => {
      const dateStr = w.観測日?.split('T')[0];
      const daySales = salesData
        .filter(s => s.売上日?.split('T')[0] === dateStr && (!currentStoreId || s.店舗ID === currentStoreId))
        .reduce((sum, s) => sum + (s.売上金額 || 0), 0);

      if (daySales > 0 && w.天気) {
        if (!weatherSales[w.天気]) {
          weatherSales[w.天気] = [];
        }
        weatherSales[w.天気].push(daySales);
      }
    });

    const avgWeatherSales = {};
    Object.keys(weatherSales).forEach(weather => {
      const sales = weatherSales[weather];
      avgWeatherSales[weather] = sales.reduce((sum, s) => sum + s, 0) / sales.length;
    });

    if (weatherChart) weatherChart.destroy();

    weatherChart = new Chart(ctx, {
      type: 'bar',
      data: {
        labels: Object.keys(avgWeatherSales),
        datasets: [{
          label: '平均売上金額',
          data: Object.values(avgWeatherSales),
          backgroundColor: 'rgba(79, 70, 229, 0.6)',
          borderColor: '#4f46e5',
          borderWidth: 1
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          y: {
            beginAtZero: true,
            ticks: {
              callback: function(value) {
                return '¥' + value.toLocaleString();
              }
            }
          }
        }
      }
    });
  }

  // イベント・季節要因表示
  function renderEvents() {
    const eventsData = tables[TABLE_EVENTS]?.records || [];
    const seasonData = tables[6]?.records || []; // 季節情報データ

    const now = new Date();
    const currentEvents = eventsData
      .filter(e => {
        const startDate = new Date(e.開始日時);
        const endDate = new Date(e.終了日時);
        return startDate <= now && endDate >= now && (!currentStoreId || e.店舗ID === currentStoreId);
      })
      .slice(0, 5);

    const eventsHtml = currentEvents.length > 0 ?
      currentEvents.map(event => `
        <div class="event-item">
          <div class="event-title">${event.イベント名}</div>
          <div class="event-date">${new Date(event.開始日時).toLocaleDateString()} - ${new Date(event.終了日時).toLocaleDateString()}</div>
          <span class="event-impact impact-${event.影響度?.toLowerCase() || 'low'}">${event.影響度 || '低'}</span>
        </div>
      `).join('') :
      '<div class="loading">現在進行中のイベントはありません</div>';

    container.querySelector('#events-list').innerHTML = eventsHtml;
  }

  // 在庫アラート表示
  function renderAlerts() {
    // 仮想的なアラートデータ
    const alerts = [
      { title: '商品A - 在庫不足', detail: '現在在庫: 5個 / 安全在庫: 20個', type: 'critical' },
      { title: '商品B - 在庫警告', detail: '現在在庫: 15個 / 安全在庫: 30個', type: 'warning' },
      { title: '商品C - 在庫不足', detail: '現在在庫: 2個 / 安全在庫: 15個', type: 'critical' }
    ];

    const alertsHtml = alerts.map(alert => `
      <div class="alert-item ${alert.type}" onclick="window.showScreen('scr-1778591945891')">
        <div class="alert-title">${alert.title}</div>
        <div class="alert-detail">${alert.detail}</div>
      </div>
    `).join('');

    container.querySelector('#alerts-list').innerHTML = alertsHtml;
  }

  // データ更新
  function updateDashboard() {
    updateKPIs();
    renderSalesTrend();
    renderProductRanking();
    renderOrderStatus();
    renderWeatherImpact();
    renderEvents();
    renderAlerts();
  }

  // イベントリスナー
  container.querySelector('#store-select').addEventListener('change', (e) => {
    currentStoreId = e.target.value;
    updateDashboard();
  });

  container.querySelector('#period-select').addEventListener('change', (e) => {
    currentPeriod = parseInt(e.target.value);
    updateDashboard();
  });

  container.querySelector('#btn-refresh').addEventListener('click', () => {
    updateDashboard();
  });

  // 初期化
  initStoreSelect();
  updateDashboard();
}

function(container, apiUrl, tables) {
  let currentPredictions = [];
  let chartType = 'line';

  // 店舗データを読み込んでセレクトボックスに設定
  function loadStores() {
    const storeSelect = container.querySelector('#store-select');
    const storeTable = tables.find(t => t.tableName === '店舗マスタ');
    if (storeTable && storeTable.records) {
      storeTable.records.forEach(store => {
        if (store.有効フラグ) {
          const option = document.createElement('option');
          option.value = store.店舗ID;
          option.textContent = `${store.店舗コード} - ${store.店舗名}`;
          storeSelect.appendChild(option);
        }
      });
    }
  }

  // 予測結果テーブルの再描画
  function renderPredictions(predictions) {
    const tbody = container.querySelector('#prediction-table-body');
    tbody.innerHTML = predictions.map(p => `
      <tr data-id="${p.予測結果ID}">
        <td>${p.商品コード || '-'}</td>
        <td>${p.商品名 || '-'}</td>
        <td>${p.予測対象日 ? new Date(p.予測対象日).toLocaleDateString() : '-'}</td>
        <td>${p.予測数量 || 0}</td>
        <td>${p.予測精度 || 0}%</td>
        <td>${p.推奨発注数量 || 0}</td>
        <td>${p.実績数量 || '-'}</td>
        <td>
          <span style="padding: 2px 8px; border-radius: 4px; font-size: 0.8rem; 
                       background: ${p.予測ステータス === '完了' ? '#28a745' : p.予測ステータス === 'エラー' ? '#dc3545' : '#ffc107'}; 
                       color: white;">
            ${p.予測ステータス || '未実行'}
          </span>
        </td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${p.予測結果ID}">詳細</button>
        </td>
      </tr>
    `).join('');
  }

  // グラフ描画関数
  function drawPredictionChart(predictions) {
    const canvas = container.querySelector('#prediction-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (!predictions || predictions.length === 0) {
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '16px Arial';
      ctx.textAlign = 'center';
      ctx.fillText('予測データがありません', canvas.width / 2, canvas.height / 2);
      return;
    }

    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // データの準備
    const sortedData = predictions.sort((a, b) => new Date(a.予測対象日) - new Date(b.予測対象日));
    const maxValue = Math.max(...sortedData.map(d => Math.max(d.予測数量 || 0, d.実績数量 || 0)));

    // 軸の描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // データポイントの描画
    if (chartType === 'line') {
      // 予測値の線
      ctx.strokeStyle = '#007bff';
      ctx.lineWidth = 2;
      ctx.beginPath();
      sortedData.forEach((d, i) => {
        const x = padding + (i / (sortedData.length - 1)) * chartWidth;
        const y = canvas.height - padding - ((d.予測数量 || 0) / maxValue) * chartHeight;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.stroke();

      // 実績値の線
      ctx.strokeStyle = '#28a745';
      ctx.lineWidth = 2;
      ctx.beginPath();
      sortedData.forEach((d, i) => {
        if (d.実績数量) {
          const x = padding + (i / (sortedData.length - 1)) * chartWidth;
          const y = canvas.height - padding - (d.実績数量 / maxValue) * chartHeight;
          if (i === 0) ctx.moveTo(x, y);
          else ctx.lineTo(x, y);
        }
      });
      ctx.stroke();
    } else {
      // 棒グラフ
      const barWidth = chartWidth / sortedData.length * 0.8;
      sortedData.forEach((d, i) => {
        const x = padding + (i / sortedData.length) * chartWidth;

        // 予測値
        ctx.fillStyle = '#007bff';
        const predHeight = ((d.予測数量 || 0) / maxValue) * chartHeight;
        ctx.fillRect(x, canvas.height - padding - predHeight, barWidth / 2, predHeight);

        // 実績値
        if (d.実績数量) {
          ctx.fillStyle = '#28a745';
          const actualHeight = (d.実績数量 / maxValue) * chartHeight;
          ctx.fillRect(x + barWidth / 2, canvas.height - padding - actualHeight, barWidth / 2, actualHeight);
        }
      });
    }

    // 凡例
    ctx.fillStyle = '#007bff';
    ctx.fillRect(canvas.width - 150, 20, 15, 15);
    ctx.fillStyle = '#d0e4ff';
    ctx.font = '12px Arial';
    ctx.textAlign = 'left';
    ctx.fillText('予測値', canvas.width - 130, 32);

    ctx.fillStyle = '#28a745';
    ctx.fillRect(canvas.width - 150, 40, 15, 15);
    ctx.fillStyle = '#d0e4ff';
    ctx.fillText('実績値', canvas.width - 130, 52);
  }

  // 比較チャート描画
  function drawComparisonChart(predictions) {
    const canvas = container.querySelector('#comparison-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (!predictions || predictions.length === 0) {
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '16px Arial';
      ctx.textAlign = 'center';
      ctx.fillText('比較データがありません', canvas.width / 2, canvas.height / 2);
      return;
    }

    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // 実績データがある予測のみ
    const comparisonData = predictions.filter(p => p.実績数量);

    if (comparisonData.length === 0) {
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '16px Arial';
      ctx.textAlign = 'center';
      ctx.fillText('実績データがまだありません', canvas.width / 2, canvas.height / 2);
      return;
    }

    // 軸の描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // 散布図として描画
    const maxValue = Math.max(...comparisonData.map(d => Math.max(d.予測数量 || 0, d.実績数量 || 0)));

    comparisonData.forEach(d => {
      const x = padding + ((d.予測数量 || 0) / maxValue) * chartWidth;
      const y = canvas.height - padding - ((d.実績数量 || 0) / maxValue) * chartHeight;

      ctx.fillStyle = '#007bff';
      ctx.beginPath();
      ctx.arc(x, y, 4, 0, 2 * Math.PI);
      ctx.fill();
    });

    // 理想線（y=x）
    ctx.strokeStyle = '#dc3545';
    ctx.lineWidth = 1;
    ctx.setLineDash([5, 5]);
    ctx.beginPath();
    ctx.moveTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, padding);
    ctx.stroke();
    ctx.setLineDash([]);
  }

  // エラー表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    const errorText = container.querySelector('#error-text');
    errorText.textContent = message;
    errorDiv.classList.remove('hidden');

    setTimeout(() => {
      errorDiv.classList.add('hidden');
    }, 5000);
  }

  // バリデーション
  function validateForm() {
    const storeId = container.querySelector('#store-select').value;
    const category = container.querySelector('#category-select').value;
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;
    const models = container.querySelectorAll('input[name="prediction-model"]:checked');

    if (!storeId) {
      showError('店舗を選択してください');
      return false;
    }
    if (!category) {
      showError('商品カテゴリを選択してください');
      return false;
    }
    if (!startDate || !endDate) {
      showError('予測期間を設定してください');
      return false;
    }
    if (new Date(startDate) >= new Date(endDate)) {
      showError('開始日は終了日より前の日付を入力してください');
      return false;
    }
    if (new Date(startDate) < new Date()) {
      showError('開始日は現在日以降の日付を設定してください');
      return false;
    }
    if (models.length === 0) {
      showError('予測モデルを選択してください');
      return false;
    }

    return true;
  }

  // AI予測実行
  async function executePrediction() {
    if (!validateForm()) return;

    const loadingDiv = container.querySelector('#prediction-loading');
    const resultsDiv = container.querySelector('#prediction-results');

    loadingDiv.classList.remove('hidden');
    resultsDiv.classList.add('hidden');

    try {
      // 模擬的な予測処理（実際のAI処理の代替）
      await new Promise(resolve => setTimeout(resolve, 3000));

      // 模擬予測結果の生成
      const storeId = container.querySelector('#store-select').value;
      const category = container.querySelector('#category-select').value;
      const startDate = new Date(container.querySelector('#start-date').value);
      const endDate = new Date(container.querySelector('#end-date').value);

      const mockPredictions = [];
      const currentDate = new Date(startDate);
      let productIndex = 1;

      while (currentDate <= endDate) {
        const prediction = {
          予測結果ID: `pred-${Date.now()}-${productIndex}`,
          店舗ID: storeId,
          商品ID: `product-${productIndex}`,
          商品コード: `P${String(productIndex).padStart(4, '0')}`,
          商品名: `${category}商品${productIndex}`,
          予測対象日: new Date(currentDate).toISOString(),
          予測数量: Math.floor(Math.random() * 100) + 20,
          予測精度: Math.floor(Math.random() * 20) + 80,
          推奨発注数量: Math.floor(Math.random() * 120) + 30,
          実績数量: Math.random() > 0.7 ? Math.floor(Math.random() * 100) + 15 : null,
          予測ステータス: '完了',
          予測モデルバージョン: 'v2.1.0'
        };
        mockPredictions.push(prediction);

        currentDate.setDate(currentDate.getDate() + 1);
        if (productIndex < 5) productIndex++;
        else productIndex = 1;
      }

      currentPredictions = mockPredictions;

      // 予測結果の保存
      for (const prediction of mockPredictions) {
        await window.aivicApi.save(6, prediction); // 需要予測結果テーブル
      }

      // 結果表示
      renderPredictions(currentPredictions);
      drawPredictionChart(currentPredictions);
      drawComparisonChart(currentPredictions);

      // 精度指標の更新
      const avgAccuracy = currentPredictions.reduce((sum, p) => sum + (p.予測精度 || 0), 0) / currentPredictions.length;
      container.querySelector('#accuracy-rate').textContent = `${avgAccuracy.toFixed(1)}%`;
      container.querySelector('#confidence-interval').textContent = '95%';
      container.querySelector('#model-version').textContent = 'v2.1.0';

      // 影響要因分析の更新
      container.querySelector('#seasonal-impact').textContent = '中程度 (15%)';
      container.querySelector('#weather-impact').textContent = '高 (25%)';
      container.querySelector('#event-impact').textContent = '低 (5%)';

      // 外部要因情報の更新
      container.querySelector('#weather-info').textContent = '晴れ時々曇り、気温22-28℃';
      container.querySelector('#event-info').textContent = '地域祭り (影響度: 中)';

      loadingDiv.classList.add('hidden');
      resultsDiv.classList.remove('hidden');

    } catch (error) {
      loadingDiv.classList.add('hidden');
      showError('予測処理中にエラーが発生しました: ' + error.message);
    }
  }

  // CSVエクスポート
  function exportCSV() {
    if (currentPredictions.length === 0) {
      showError('エクスポートする予測データがありません');
      return;
    }

    const headers = ['商品コード', '商品名', '予測対象日', '予測数量', '予測精度', '推奨発注数量', '実績数量', 'ステータス'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...currentPredictions.map(p => [
        p.商品コード || '',
        p.商品名 || '',
        p.予測対象日 ? new Date(p.予測対象日).toLocaleDateString() : '',
        p.予測数量 || 0,
        (p.予測精度 || 0) + '%',
        p.推奨発注数量 || 0,
        p.実績数量 || '',
        p.予測ステータス || ''
      ].map(field => `"${field}"`).join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `需要予測結果_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期化
  loadStores();

  // イベントリスナー
  container.querySelector('#btn-predict').addEventListener('click', executePrediction);

  container.querySelector('#btn-reset').addEventListener('click', () => {
    container.querySelector('#store-select').value = '';
    container.querySelector('#category-select').value = '';
    container.querySelector('#start-date').value = '';
    container.querySelector('#end-date').value = '';
    container.querySelectorAll('input[name="prediction-model"]').forEach(cb => cb.checked = false);
    container.querySelector('#prediction-results').classList.add('hidden');
    currentPredictions = [];
  });

  container.querySelector('#btn-chart-line').addEventListener('click', () => {
    chartType = 'line';
    drawPredictionChart(currentPredictions);
  });

  container.querySelector('#btn-chart-bar').addEventListener('click', () => {
    chartType = 'bar';
    drawPredictionChart(currentPredictions);
  });

  container.querySelector('#btn-export-csv').addEventListener('click', exportCSV);

  container.querySelector('#product-search').addEventListener('input', (e) => {
    const keyword = e.target.value.toLowerCase();
    const filtered = currentPredictions.filter(p => 
      (p.商品名 || '').toLowerCase().includes(keyword) ||
      (p.商品コード || '').toLowerCase().includes(keyword)
    );
    renderPredictions(filtered);
  });

  // 詳細ボタンのイベントデリゲーション
  container.addEventListener('click', (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      const predictionId = detailBtn.dataset.id;
      window.showScreen('scr-1778591885672'); // AI需要予測処理画面
    }
  });
}

function(container, apiUrl, tables) {
  let currentProducts = [];
  let currentStore = null;
  let demandPredictions = {};
  let inventoryData = {};

  // 初期データの設定
  const storeTable = tables.find(t => t.tableName === '店舗マスタ') || tables[1];
  const productTable = tables.find(t => t.tableName === '商品マスタ') || tables[2];
  const predictionTable = tables.find(t => t.tableName === '需要予測結果') || tables[8];
  const orderTable = tables.find(t => t.tableName === '発注データ') || tables[9];

  // 店舗選択肢を設定
  const storeSelect = container.querySelector('#select-store');
  if (storeTable && storeTable.records) {
    storeTable.records.forEach(store => {
      if (store.有効フラグ) {
        const option = document.createElement('option');
        option.value = store.店舗ID || store.id;
        option.textContent = `${store.店舗コード || ''} - ${store.店舗名 || ''}`;
        storeSelect.appendChild(option);
      }
    });
  }

  // 商品テーブル再描画関数
  function renderProducts(products) {
    const tbody = container.querySelector('#product-tbody');
    const tableWrap = container.querySelector('#product-table-wrap');
    const noStoreMsg = container.querySelector('#no-store-message');
    const noResultsMsg = container.querySelector('#no-results-message');

    if (!currentStore) {
      tableWrap.classList.add('hidden');
      noStoreMsg.classList.remove('hidden');
      noResultsMsg.classList.add('hidden');
      return;
    }

    noStoreMsg.classList.add('hidden');

    if (!products || products.length === 0) {
      tableWrap.classList.add('hidden');
      noResultsMsg.classList.remove('hidden');
      return;
    }

    noResultsMsg.classList.add('hidden');
    tableWrap.classList.remove('hidden');

    tbody.innerHTML = products.map(product => {
      const productId = product.商品ID || product.id;
      const prediction = demandPredictions[productId] || {};
      const inventory = inventoryData[productId] || 0;

      return `
        <tr data-id="${productId}">
          <td>${product.商品コード || ''}</td>
          <td>${product.商品名|| ''}</td>
          <td>${getCategoryName(product.商品カテゴリID)}</td>
          <td>${inventory}</td>
          <td>${prediction.予測数量 || 0}</td>
          <td>${prediction.推奨発注数量 || 0}</td>
          <td>
            <input type="number" class="input order-quantity" data-product-id="${productId}" 
                   value="${prediction.推奨発注数量 || 0}" min="0" style="width: 80px;" 
                   data-testid="order-quantity-${productId}">
            <button class="action-btn secondary adjust-btn" data-product-id="${productId}" data-action="increase">+</button>
            <button class="action-btn secondary adjust-btn" data-product-id="${productId}" data-action="decrease">-</button>
          </td>
          <td>
            <input type="text" class="input order-reason" data-product-id="${productId}" 
                   placeholder="発注理由" style="width: 120px;" data-testid="order-reason-${productId}">
          </td>
          <td>
            <button class="action-btn order-btn" data-product-id="${productId}" data-testid="order-button-${productId}">発注</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // カテゴリ名取得
  function getCategoryName(categoryId) {
    const categories = {
      'cat1': '食品',
      'cat2': '日用品', 
      'cat3': '衣料品',
      'cat4': '家電'
    };
    return categories[categoryId] || '未分類';
  }

  // 需要予測結果表示
  function renderPredictionResults(storeId) {
    const predictionArea = container.querySelector('#prediction-area');
    if (!storeId) {
      predictionArea.innerHTML = '店舗を選択すると需要予測結果が表示されます';
      return;
    }

    const storeName = getStoreName(storeId);
    const totalPrediction = Object.values(demandPredictions).reduce((sum, p) => sum + (p.予測数量 || 0), 0);
    const totalRecommended = Object.values(demandPredictions).reduce((sum, p) => sum + (p.推奨発注数量 || 0), 0);

    predictionArea.innerHTML = `
      <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 15px;">
        <div>
          <div style="color: var(--text-muted); font-size: 14px;">対象店舗</div>
          <div style="color: var(--text); font-weight: bold;">${storeName}</div>
        </div>
        <div>
          <div style="color: var(--text-muted); font-size: 14px;">総予測需要量</div>
          <div style="color: var(--text); font-weight: bold;">${totalPrediction}個</div>
        </div>
        <div>
          <div style="color: var(--text-muted); font-size: 14px;">総推奨発注量</div>
          <div style="color: var(--text); font-weight: bold;">${totalRecommended}個</div>
        </div>
        <div>
          <div style="color: var(--text-muted); font-size: 14px;">予測精度</div>
          <div style="color: var(--text); font-weight: bold;">85%</div>
        </div>
      </div>
    `;
  }

  // 店舗名取得
  function getStoreName(storeId) {
    const store = storeTable.records?.find(s => (s.店舗ID || s.id) === storeId);
    return store ? `${store.店舗コード || ''} - ${store.店舗名 || ''}` : '不明';
  }

  // 商品データ読み込み
  async function loadProducts(storeId) {
    if (!storeId) {
      currentProducts = [];
      renderProducts([]);
      return;
    }

    try {
      // 商品データ取得
      const products = await window.aivicApi.list(2) || productTable.records || [];

      // 需要予測データ取得
      const predictions = await window.aivicApi.list(8) || predictionTable.records || [];
      demandPredictions = {};
      predictions.forEach(p => {
        if ((p.店舗ID || p.storeId) === storeId) {
          demandPredictions[p.商品ID || p.productId] = p;
        }
      });

      // 在庫データをサンプル生成
      inventoryData = {};
      products.forEach(p => {
        inventoryData[p.商品ID || p.id] = Math.floor(Math.random() * 100) + 10;
      });

      currentProducts = products.filter(p => p.有効フラグ !== false);
      currentStore = storeId;

      renderProducts(currentProducts);
      renderPredictionResults(storeId);
    } catch (error) {
      console.error('商品データの読み込みに失敗:', error);
      currentProducts = [];
      renderProducts([]);
    }
  }

  // 検索・フィルタ処理
  function filterProducts() {
    if (!currentStore) {
      renderProducts([]);
      return;
    }

    let filtered = [...currentProducts];

    // カテゴリフィルタ
    const category = container.querySelector('#select-category').value;
    if (category) {
      const categoryMap = {
        '食品': 'cat1',
        '日用品': 'cat2', 
        '衣料品': 'cat3',
        '家電': 'cat4'
      };
      filtered = filtered.filter(p => p.商品カテゴリID === categoryMap[category]);
    }

    // 商品名検索
    const searchTerm = container.querySelector('#input-search').value.toLowerCase();
    if (searchTerm) {
      filtered = filtered.filter(p => 
        (p.商品名 || '').toLowerCase().includes(searchTerm) ||
        (p.商品コード || '').toLowerCase().includes(searchTerm)
      );
    }

    renderProducts(filtered);
  }

  // バリデーション
  function validateOrderQuantity(quantity) {
    if (quantity === '' || quantity === null || quantity === undefined) {
      return { valid: false, message: '発注量を入力してください' };
    }

    const num = parseFloat(quantity);
    if (isNaN(num)) {
      return { valid: false, message: '発注量は数値で入力してください' };
    }

    if (num < 0) {
      return { valid: false, message: '発注量は正の数値を入力してください' };
    }

    if (num === 0) {
      return { valid: false, message: '発注量は1以上を入力してください' };
    }

    return { valid: true };
  }

  // 日付バリデーション
  function validateDateRange() {
    const startDate = container.querySelector('#input-date-start').value;
    const endDate = container.querySelector('#input-date-end').value;

    if (startDate && endDate && startDate > endDate) {
      alert('終了日は開始日以降の日付を入力してください');
      return false;
    }
    return true;
  }

  // 発注処理
  async function processOrder(productId, quantity, reason) {
    const validation = validateOrderQuantity(quantity);
    if (!validation.valid) {
      alert(validation.message);
      return false;
    }

    const product = currentProducts.find(p => (p.商品ID || p.id) === productId);
    if (!product) {
      alert('商品情報が見つかりません');
      return false;
    }

    // 発注確認モーダル表示
    const modal = container.querySelector('#order-modal');
    const details = container.querySelector('#order-details');

    details.innerHTML = `
      <div><strong>商品:</strong> ${product.商品名}</div>
      <div><strong>商品コード:</strong> ${product.商品コード}</div>
      <div><strong>発注量:</strong> ${quantity}個</div>
      <div><strong>発注理由:</strong> ${reason || '通常発注'}</div>
      <div><strong>発注金額:</strong> ${(quantity * (product.単価 || 0)).toLocaleString()}円</div>
    `;

    modal.classList.remove('hidden');

    return new Promise((resolve) => {
      const confirmBtn = container.querySelector('#btn-confirm-order');
      const cancelBtn = container.querySelector('#btn-cancel-order');

      const handleConfirm = async () => {
        try {
          const orderData = {
            店舗ID: currentStore,
            商品ID: productId,
            発注日: new Date().toISOString(),
            納期予定日: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(),
            発注数量: parseInt(quantity),
            発注単価: product.単価 || 0,
            発注金額: quantity * (product.単価 || 0),
            発注方法: reason ? 'AI推奨修正' : 'AI推奨採用',
            発注ステータス: '発注済',
            発注理由: reason || '通常発注',
            自動発注フラグ: false,
            作成日時: new Date().toISOString(),
            更新日時: new Date().toISOString(),
            作成者ID: 'current-user',
            更新者ID: 'current-user'
          };

          const result = await window.aivicApi.save(9, orderData);
          if (result) {
            alert('発注が完了しました');
            modal.classList.add('hidden');
            resolve(true);
          } else {
            alert('発注処理に失敗しました');
            resolve(false);
          }
        } catch (error) {
          console.error('発注エラー:', error);
          alert('発注処理でエラーが発生しました');
          resolve(false);
        }

        confirmBtn.removeEventListener('click', handleConfirm);
        cancelBtn.removeEventListener('click', handleCancel);
      };

      const handleCancel = () => {
        modal.classList.add('hidden');
        resolve(false);
        confirmBtn.removeEventListener('click', handleConfirm);
        cancelBtn.removeEventListener('click', handleCancel);
      };

      confirmBtn.addEventListener('click', handleConfirm);
      cancelBtn.addEventListener('click', handleCancel);
    });
  }

  // CSVエクスポート
  async function exportCSV() {
    try {
      const orders = await window.aivicApi.list(9) || [];
      const headers = ['発注ID', '店舗名', '商品名', '発注日', '発注数量', '発注金額', '発注ステータス', '発注理由'];

      let csvContent = '\uFEFF' + headers.join(',') + '\n';

      orders.forEach(order => {
        const storeName = getStoreName(order.店舗ID);
        const product = currentProducts.find(p => (p.商品ID || p.id) === order.商品ID);
        const productName = product ? product.商品名 : '不明';

        const row = [
          order.発注ID || order.id || '',
          `"${storeName}"`,
          `"${productName}"`,
          order.発注日 || '',
          order.発注数量 || 0,
          order.発注金額 || 0,
          order.発注ステータス || '',
          `"${order.発注理由 || ''}"`
        ];
        csvContent += row.join(',') + '\n';
      });

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `発注データ_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    } catch (error) {
      console.error('CSVエクスポートエラー:', error);
      alert('CSVエクスポートに失敗しました');
    }
  }

  // イベントリスナー設定

  // 店舗選択
  container.querySelector('#select-store').addEventListener('change', (e) => {
    loadProducts(e.target.value);
  });

  // カテゴリ選択
  container.querySelector('#select-category').addEventListener('change', filterProducts);

  // 検索ボタン
  container.querySelector('#btn-search').addEventListener('click', () => {
    if (!validateDateRange()) return;
    filterProducts();
  });

  // CSVエクスポートボタン
  container.querySelector('#btn-export').addEventListener('click', exportCSV);

  // 商品検索（リアルタイム）
  container.querySelector('#input-search').addEventListener('input', filterProducts);

  // イベントデリゲーション
  container.addEventListener('click', async (e) => {
    // 発注量調整ボタン
    const adjustBtn = e.target.closest('.adjust-btn');
    if (adjustBtn) {
      const productId = adjustBtn.dataset.productId;
      const action = adjustBtn.dataset.action;
      const quantityInput = container.querySelector(`input[data-product-id="${productId}"]`);
      let currentValue = parseInt(quantityInput.value) || 0;

      if (action === 'increase') {
        quantityInput.value = currentValue + 1;
      } else if (action === 'decrease' && currentValue > 0) {
        quantityInput.value = currentValue - 1;
      }
      return;
    }

    // 発注ボタン
    const orderBtn = e.target.closest('.order-btn');
    if (orderBtn) {
      const productId = orderBtn.dataset.productId;
      const quantityInput = container.querySelector(`input.order-quantity[data-product-id="${productId}"]`);
      const reasonInput = container.querySelector(`input.order-reason[data-product-id="${productId}"]`);

      const quantity = quantityInput.value;
      const reason = reasonInput.value;

      await processOrder(productId, quantity, reason);
      return;
    }
  });

  // 初期表示
  renderProducts([]);
  renderPredictionResults(null);
}

function(container, apiUrl, tables) {
  let currentPage = 1;
  const itemsPerPage = 20;
  let allHistories = [];
  let filteredHistories = [];

  const tbody = container.querySelector("#history-tbody");
  const modal = container.querySelector("#detail-modal");
  const detailContent = container.querySelector("#detail-content");

  // ユーザー一覧を取得してセレクトボックスに設定
  async function loadUsers() {
    const users = await window.aivicApi.list(0); // ログインユーザーテーブル
    const userSelect = container.querySelector("#select-user");
    if (users) {
      users.forEach(user => {
        const option = document.createElement("option");
        option.value = user.ユーザー名 || "";
        option.textContent = user.ユーザー名 || "";
        userSelect.appendChild(option);
      });
    }
  }

  function formatDateTime(dateStr) {
    if (!dateStr) return "";
    const date = new Date(dateStr);
    return date.toLocaleString("ja-JP");
  }

  function renderRows(histories) {
    const startIndex = (currentPage - 1) * itemsPerPage;
    const endIndex = startIndex + itemsPerPage;
    const pageHistories = histories.slice(startIndex, endIndex);

    if (pageHistories.length === 0) {
      tbody.innerHTML = '<tr><td colspan="7" style="text-align: center; color: var(--text-muted);">該当する操作履歴が見つかりませんでした</td></tr>';
    } else {
      tbody.innerHTML = pageHistories.map(h => `
        <tr data-id="${h.操作履歴ID || h.id || ''}">
          <td>${formatDateTime(h.操作日時)}</td>
          <td>${h.ユーザー名 || ""}</td>
          <td>${h.操作種別 || ""}</td>
          <td>${h.操作画面 || ""}</td>
          <td>${h.IPアドレス || ""}</td>
          <td><span style="color: ${h.処理結果 === '成功' ? '#4ade80' : h.処理結果 === '失敗' || h.処理結果 === 'エラー' ? '#f87171' : 'var(--text)'}">${h.処理結果 || ""}</span></td>
          <td><button class="action-btn secondary detail-btn" data-id="${h.操作履歴ID || h.id || ''}">詳細</button></td>
        </tr>
      `).join("");
    }

    updatePagination(histories.length);
  }

  function updatePagination(totalItems) {
    const totalPages = Math.ceil(totalItems / itemsPerPage);
    const pageInfo = container.querySelector("#page-info");
    const btnPrev = container.querySelector("#btn-prev");
    const btnNext = container.querySelector("#btn-next");

    pageInfo.textContent = `${currentPage} / ${Math.max(1, totalPages)}`;
    btnPrev.disabled = currentPage <= 1;
    btnNext.disabled = currentPage >= totalPages;
  }

  function filterHistories() {
    const startDate = container.querySelector("#input-start-date").value;
    const endDate = container.querySelector("#input-end-date").value;
    const user = container.querySelector("#select-user").value;
    const operationType = container.querySelector("#select-operation-type").value;
    const screenName = container.querySelector("#input-screen-name").value.toLowerCase();
    const ipAddress = container.querySelector("#input-ip-address").value;
    const result = container.querySelector("#select-result").value;

    // 日付バリデーション
    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      alert("開始日が終了日より後の日付になっています。正しい日付範囲を入力してください。");
      return;
    }

    // IPアドレスバリデーション
    if (ipAddress && !isValidIPAddress(ipAddress)) {
      alert("不正なIPアドレス形式です。正しい形式で入力してください。");
      return;
    }

    filteredHistories = allHistories.filter(h => {
      if (startDate && h.操作日時 && new Date(h.操作日時) < new Date(startDate)) return false;
      if (endDate && h.操作日時 && new Date(h.操作日時) > new Date(endDate + "T23:59:59")) return false;
      if (user && h.ユーザー名 !== user) return false;
      if (operationType && h.操作種別 !== operationType) return false;
      if (screenName && !h.操作画面?.toLowerCase().includes(screenName)) return false;
      if (ipAddress && h.IPアドレス !== ipAddress) return false;
      if (result && h.処理結果 !== result) return false;
      return true;
    });

    currentPage = 1;
    renderRows(filteredHistories);
  }

  function isValidIPAddress(ip) {
    const ipRegex = /^(?:(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$/;
    return ipRegex.test(ip);
  }

  function clearFilters() {
    container.querySelector("#input-start-date").value = "";
    container.querySelector("#input-end-date").value = "";
    container.querySelector("#select-user").value = "";
    container.querySelector("#select-operation-type").value = "";
    container.querySelector("#input-screen-name").value = "";
    container.querySelector("#input-ip-address").value = "";
    container.querySelector("#select-result").value = "";

    filteredHistories = [...allHistories];
    currentPage = 1;
    renderRows(filteredHistories);
  }

  function showDetailModal(historyId) {
    const history = allHistories.find(h => (h.操作履歴ID || h.id) === historyId);
    if (!history) return;

    detailContent.innerHTML = `
      <div style="display: grid; gap: 12px;">
        <div><strong>操作日時:</strong> ${formatDateTime(history.操作日時)}</div>
        <div><strong>ユーザー名:</strong> ${history.ユーザー名 || ""}</div>
        <div><strong>操作種別:</strong> ${history.操作種別 || ""}</div>
        <div><strong>操作画面:</strong> ${history.操作画面 || ""}</div>
        <div><strong>操作対象テーブル:</strong> ${history.操作対象テーブル || ""}</div>
        <div><strong>操作対象ID:</strong> ${history.操作対象ID || ""}</div>
        <div><strong>操作内容:</strong> ${history.操作内容 || ""}</div>
        <div><strong>IPアドレス:</strong> ${history.IPアドレス || ""}</div>
        <div><strong>ユーザーエージェント:</strong> ${history.ユーザーエージェント || ""}</div>
        <div><strong>処理結果:</strong> <span style="color: ${history.処理結果 === '成功' ? '#4ade80' : history.処理結果 === '失敗' || history.処理結果 === 'エラー' ? '#f87171' : 'var(--text)'}">${history.処理結果 || ""}</span></div>
        ${history.エラーメッセージ ? `<div><strong>エラーメッセージ:</strong> ${history.エラーメッセージ}</div>` : ""}
        <div><strong>処理時間:</strong> ${history.処理時間 || ""}ms</div>
      </div>
    `;

    modal.classList.remove("hidden");
  }

  function exportCSV() {
    if (filteredHistories.length > 100000) {
      alert("データ量が多すぎるため、CSV出力でタイムアウトエラーが発生する可能性があります。検索条件を絞り込んでから再度お試しください。");
      return;
    }

    const headers = ["操作日時", "ユーザー名", "操作種別", "操作画面", "操作対象テーブル", "操作対象ID", "操作内容", "IPアドレス", "ユーザーエージェント", "処理結果", "エラーメッセージ", "処理時間"];
    const csvContent = [
      headers.join(","),
      ...filteredHistories.map(h => [
        `"${formatDateTime(h.操作日時)}"`,
        `"${h.ユーザー名 || ""}"`,
        `"${h.操作種別 || ""}"`,
        `"${h.操作画面 || ""}"`,
        `"${h.操作対象テーブル || ""}"`,
        `"${h.操作対象ID || ""}"`,
        `"${(h.操作内容 || "").replace(/"/g, '""')}"`,
        `"${h.IPアドレス || ""}"`,
        `"${(h.ユーザーエージェント || "").replace(/"/g, '""')}"`,
        `"${h.処理結果 || ""}"`,
        `"${(h.エラーメッセージ || "").replace(/"/g, '""')}"`,
        `"${h.処理時間 || ""}"`
      ].join(","))
    ].join("\n");

    const blob = new Blob(["\uFEFF" + csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `system_operation_history_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期データ読み込み
  async function loadData() {
    const histories = await window.aivicApi.list(12); // システム操作履歴テーブル
    if (histories) {
      allHistories = histories.sort((a, b) => new Date(b.操作日時) - new Date(a.操作日時));
      filteredHistories = [...allHistories];
      renderRows(filteredHistories);
    } else {
      // 初期データを使用
      allHistories = (tables[12]?.records || []).sort((a, b) => new Date(b.操作日時) - new Date(a.操作日時));
      filteredHistories = [...allHistories];
      renderRows(filteredHistories);
    }
  }

  // イベントリスナー
  container.querySelector("#btn-search").addEventListener("click", filterHistories);
  container.querySelector("#btn-clear").addEventListener("click", clearFilters);
  container.querySelector("#btn-csv-export").addEventListener("click", exportCSV);

  container.querySelector("#btn-prev").addEventListener("click", () => {
    if (currentPage > 1) {
      currentPage--;
      renderRows(filteredHistories);
    }
  });

  container.querySelector("#btn-next").addEventListener("click", () => {
    const totalPages = Math.ceil(filteredHistories.length / itemsPerPage);
    if (currentPage < totalPages) {
      currentPage++;
      renderRows(filteredHistories);
    }
  });

  container.querySelector("#btn-close-modal").addEventListener("click", () => {
    modal.classList.add("hidden");
  });

  modal.addEventListener("click", (e) => {
    if (e.target === modal) {
      modal.classList.add("hidden");
    }
  });

  container.addEventListener("click", (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      showDetailModal(detailBtn.dataset.id);
    }
  });

  // 初期化
  loadUsers();
  loadData();
}

function(container, apiUrl, tables) {
  let stores = [];
  let categories = [];
  let isProcessing = false;

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      stores = await window.aivicApi.list(1) || []; // 店舗マスタ
      const products = await window.aivicApi.list(2) || []; // 商品マスタ

      // 商品カテゴリを抽出（重複除去）
      const categorySet = new Set();
      products.forEach(product => {
        if (product.商品カテゴリID) {
          categorySet.add(product.商品カテゴリID);
        }
      });
      categories = Array.from(categorySet).map(id => ({ id, name: `カテゴリ${id.slice(-4)}` }));

      renderStoreOptions();
      renderCategoryCheckboxes();
      setDefaultDates();
    } catch (error) {
      console.error('初期データ読み込みエラー:', error);
    }
  }

  // 店舗選択肢を描画
  function renderStoreOptions() {
    const storeSelect = container.querySelector('#store-select');
    storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';
    stores.filter(store => store.有効フラグ).forEach(store => {
      storeSelect.innerHTML += `<option value="${store.店舗ID}">${store.店舗名}</option>`;
    });
  }

  // 商品カテゴリチェックボックスを描画
  function renderCategoryCheckboxes() {
    const categoryList = container.querySelector('#category-list');
    categoryList.innerHTML = categories.map(category => `
      <label style="display: block; margin-bottom: 5px;">
        <input type="checkbox" class="category-checkbox" value="${category.id}"> ${category.name}
      </label>
    `).join('');
  }

  // デフォルト日付設定
  function setDefaultDates() {
    const today = new Date();
    const tomorrow = new Date(today);
    tomorrow.setDate(today.getDate() + 1);
    const nextWeek = new Date(today);
    nextWeek.setDate(today.getDate() + 7);
    const lastMonth = new Date(today);
    lastMonth.setMonth(today.getMonth() - 1);

    container.querySelector('#prediction-start-date').value = tomorrow.toISOString().split('T')[0];
    container.querySelector('#prediction-end-date').value = nextWeek.toISOString().split('T')[0];
    container.querySelector('#learning-start-date').value = lastMonth.toISOString().split('T')[0];
    container.querySelector('#learning-end-date').value = today.toISOString().split('T')[0];
  }

  // バリデーション
  function validateForm() {
    const errors = [];

    const predictionStart = container.querySelector('#prediction-start-date').value;
    const predictionEnd = container.querySelector('#prediction-end-date').value;
    const storeId = container.querySelector('#store-select').value;
    const selectedCategories = container.querySelectorAll('.category-checkbox:checked');
    const selectedModel = container.querySelector('input[name="prediction-model"]:checked');
    const learningStart = container.querySelector('#learning-start-date').value;
    const learningEnd = container.querySelector('#learning-end-date').value;

    if (!predictionStart || !predictionEnd) {
      errors.push('予測対象期間を選択してください');
    }
    if (!storeId) {
      errors.push('店舗を選択してください');
    }
    if (selectedCategories.length === 0) {
      errors.push('商品カテゴリを選択してください');
    }
    if (!selectedModel) {
      errors.push('予測モデルを選択してください');
    }
    if (!learningStart || !learningEnd) {
      errors.push('学習データ期間の開始日と終了日を入力してください');
    }

    // 日付バリデーション
    if (predictionStart && predictionEnd) {
      const startDate = new Date(predictionStart);
      const endDate = new Date(predictionEnd);
      const today = new Date();
      today.setHours(0, 0, 0, 0);

      if (startDate < today || endDate < today) {
        errors.push('予測期間に過去の日付は指定できません');
      }

      const diffTime = Math.abs(endDate - startDate);
      const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
      if (diffDays > 365) {
        errors.push('予測期間は1年以内で設定してください');
      }
    }

    // 学習データ期間バリデーション
    if (learningStart && learningEnd && predictionStart && predictionEnd) {
      const learningDays = Math.ceil((new Date(learningEnd) - new Date(learningStart)) / (1000 * 60 * 60 * 24));
      const predictionDays = Math.ceil((new Date(predictionEnd) - new Date(predictionStart)) / (1000 * 60 * 60 * 24));

      if (learningDays < predictionDays) {
        errors.push('学習データ期間は予測期間以上に設定してください');
      }
    }

    return errors;
  }

  // 進捗バー更新
