function(container, apiUrl, tables) {
  let selectedProduct = null;
  let predictionResults = [];
  let calculationResult = null;

  // DOM要素の取得
  const storeSelect = container.querySelector('#store-select');
  const categorySelect = container.querySelector('#category-select');
  const productSearch = container.querySelector('#product-search');
  const periodStart = container.querySelector('#period-start');
  const periodEnd = container.querySelector('#period-end');
  const productResults = container.querySelector('#product-results');
  const predictionResultsDiv = container.querySelector('#prediction-results');
  const currentStock = container.querySelector('#current-stock');
  const safetyStock = container.querySelector('#safety-stock');
  const leadTime = container.querySelector('#lead-time');
  const weatherImpact = container.querySelector('#weather-impact');
  const eventImpact = container.querySelector('#event-impact');
  const seasonalFactor = container.querySelector('#seasonal-factor');
  const aiRecommendedQty = container.querySelector('#ai-recommended-qty');
  const manualAdjustment = container.querySelector('#manual-adjustment');
  const finalOrderQty = container.querySelector('#final-order-qty');
  const errorMessages = container.querySelector('#error-messages');

  // エラーメッセージ表示関数
  function showError(message) {
    errorMessages.textContent = message;
    errorMessages.classList.remove('hidden');
    setTimeout(() => {
      errorMessages.classList.add('hidden');
    }, 5000);
  }

  // バリデーション関数
  function validateInputs() {
    const errors = [];

    if (!storeSelect.value) {
      errors.push('店舗を選択してください');
    }

    if (!selectedProduct) {
      errors.push('商品を選択してください');
    }

    if (!periodStart.value || !periodEnd.value) {
      errors.push('対象期間を設定してください');
    }

    if (periodStart.value && periodEnd.value && new Date(periodStart.value) > new Date(periodEnd.value)) {
      errors.push('開始日は終了日より前の日付を設定してください');
    }

    const currentStockVal = parseInt(currentStock.value) || 0;
    if (currentStockVal < 0) {
      errors.push('在庫数は0以上の値を入力してください');
    }

    const safetyStockVal = safetyStock.value;
    if (safetyStockVal && (isNaN(safetyStockVal) || parseInt(safetyStockVal) < 0)) {
      errors.push('安全在庫は0以上の数値を入力してください');
    }

    const leadTimeVal = parseInt(leadTime.value);
    if (leadTimeVal && (leadTimeVal < 1 || leadTimeVal > 365)) {
      errors.push('リードタイムは1-365日の範囲で入力してください');
    }

    const weatherVal = parseInt(weatherImpact.value);
    if (weatherVal < 0 || weatherVal > 200) {
      errors.push('天候影響度は0-200%の範囲で設定してください');
    }

    const eventVal = parseInt(eventImpact.value);
    if (eventVal < 0 || eventVal > 200) {
      errors.push('イベント影響度は0-200%の範囲で設定してください');
    }

    const seasonalVal = parseFloat(seasonalFactor.value);
    if (seasonalVal && (seasonalVal < 0.1 || seasonalVal > 10)) {
      errors.push('季節補正係数は0.1-10の範囲で入力してください');
    }

    const manualVal = manualAdjustment.value;
    if (manualVal && (isNaN(manualVal) || parseInt(manualVal) < 0)) {
      errors.push('発注量は0以上の値を入力してください');
    }

    return errors;
  }

  // 店舗データの読み込み
  async function loadStores() {
    const stores = await window.aivicApi.list(1); // 店舗マスタ
    if (stores) {
      storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';
      stores.filter(s => s.有効フラグ).forEach(store => {
        const option = document.createElement('option');
        option.value = store.id;
        option.textContent = `${store.店舗コード} - ${store.店舗名}`;
        storeSelect.appendChild(option);
      });
    }
  }

  // 商品検索
  async function searchProducts() {
    const keyword = productSearch.value.trim();
    const categoryId = categorySelect.value;

    if (!keyword && !categoryId) {
      productResults.innerHTML = '<p class="muted">商品を検索・選択してください</p>';
      return;
    }

    const products = await window.aivicApi.list(2); // 商品マスタ
    if (products) {
      let filtered = products.filter(p => p.有効フラグ);

      if (keyword) {
        filtered = filtered.filter(p => 
          p.商品名.includes(keyword) || 
          p.商品コード.includes(keyword)
        );
      }

      if (categoryId) {
        filtered = filtered.filter(p => p.商品カテゴリID === categoryId);
      }

      if (filtered.length === 0) {
        productResults.innerHTML = '<p class="muted">該当する商品が見つかりません</p>';
        return;
      }

      productResults.innerHTML = filtered.map(product => `
        <div class="product-item" data-id="${product.id}">
          <strong>${product.商品名}</strong><br>
          <span class="muted">JANコード: ${product.商品コード} | 単価: ¥${product.単価.toLocaleString()}</span>
        </div>
      `).join('');
    }
  }

  // AI予測実行
  async function executePrediction() {
    const errors = validateInputs();
    if (errors.length > 0) {
      showError(errors[0]);
      return;
    }

    const predictionStatus = container.querySelector('#prediction-status');
    predictionStatus.textContent = '予測実行中...';

    // 模擬的なAI予測結果を生成
    setTimeout(() => {
      const baseQty = Math.floor(Math.random() * 100) + 50;
      const accuracy = Math.floor(Math.random() * 20) + 80;

      predictionResults = [{
        商品ID: selectedProduct.id,
        商品名: selectedProduct.商品名,
        予測数量: baseQty,
        予測精度: accuracy,
        推奨発注数量: Math.ceil(baseQty * 1.1)
      }];

      predictionResultsDiv.innerHTML = `
        <div class="prediction-item">
          <h4>${selectedProduct.商品名}</h4>
          <div class="prediction-details">
            <div class="prediction-detail">予測数量: <strong>${baseQty}個</strong></div>
            <div class="prediction-detail">予測精度: <strong>${accuracy}%</strong></div>
            <div class="prediction-detail">推奨発注量: <strong>${Math.ceil(baseQty * 1.1)}個</strong></div>
          </div>
        </div>
      `;

      predictionStatus.textContent = '予測完了';
    }, 2000);
  }

  // 発注量計算
  function calculateOrderQuantity() {
    const errors = validateInputs();
    if (errors.length > 0) {
      showError(errors[0]);
      return;
    }

    if (predictionResults.length === 0) {
      showError('先にAI予測を実行してください');
      return;
    }

    const prediction = predictionResults[0];
    const currentStockVal = parseInt(currentStock.value) || 0;
    const safetyStockVal = parseInt(safetyStock.value) || 0;
    const leadTimeVal = parseInt(leadTime.value) || 7;
    const weatherVal = parseInt(weatherImpact.value) / 100;
    const eventVal = parseInt(eventImpact.value) / 100;
    const seasonalVal = parseFloat(seasonalFactor.value) || 1.0;

    // 発注量計算ロジック
    let adjustedDemand = prediction.予測数量 * weatherVal * eventVal * seasonalVal;
    let leadTimeDemand = adjustedDemand * (leadTimeVal / 7); // 週単位で調整
    let recommendedQty = Math.max(0, Math.ceil(leadTimeDemand + safetyStockVal - currentStockVal));

    // 最小発注数量を考慮（商品マスタから取得）
    if (selectedProduct.最小発注数量) {
      recommendedQty = Math.ceil(recommendedQty / selectedProduct.最小発注数量) * selectedProduct.最小発注数量;
    }

    calculationResult = {
      推奨発注量: recommendedQty,
      調整後需要: Math.ceil(adjustedDemand),
      リードタイム需要: Math.ceil(leadTimeDemand)
    };

    aiRecommendedQty.textContent = `${recommendedQty}個`;
    updateFinalQuantity();
  }

  // 最終発注量更新
  function updateFinalQuantity() {
    if (!calculationResult) return;

    const manualVal = parseInt(manualAdjustment.value);
    const finalQty = manualVal || calculationResult.推奨発注量;

    finalOrderQty.textContent = `${finalQty}個`;

    // 発注書作成ボタンの有効化
    const createOrderBtn = container.querySelector('#btn-create-order');
    createOrderBtn.disabled = false;
  }

  // リセット機能
  function resetForm() {
    selectedProduct = null;
    predictionResults = [];
    calculationResult = null;

    storeSelect.value = '';
    categorySelect.value = '';
    productSearch.value = '';
    periodStart.value = '';
    periodEnd.value = '';
    currentStock.value = '';
    safetyStock.value = '';
    leadTime.value = '';
    weatherImpact.value = '100';
    eventImpact.value = '100';
    seasonalFactor.value = '1.0';
    manualAdjustment.value = '';

    productResults.innerHTML = '<p class="muted">商品を検索・選択してください</p>';
    predictionResultsDiv.innerHTML = '<p class="muted">AI予測を実行してください</p>';
    aiRecommendedQty.textContent = '-';
    finalOrderQty.textContent = '-';

    container.querySelector('#prediction-status').textContent = '';
    container.querySelector('#weather-impact-value').textContent = '100%';
    container.querySelector('#event-impact-value').textContent = '100%';
    container.querySelector('#btn-create-order').disabled = true;
  }

  // イベントリスナーの設定
  container.querySelector('#btn-product-search').addEventListener('click', searchProducts);
  container.querySelector('#btn-ai-prediction').addEventListener('click', executePrediction);
  container.querySelector('#btn-calculate').addEventListener('click', calculateOrderQuantity);
  container.querySelector('#btn-reset').addEventListener('click', resetForm);

  // 商品選択
  container.addEventListener('click', (e) => {
    const productItem = e.target.closest('.product-item');
    if (productItem) {
      // 既存の選択を解除
      container.querySelectorAll('.product-item').forEach(item => {
        item.classList.remove('selected');
      });

      // 新しい選択を設定
      productItem.classList.add('selected');
      const productId = productItem.dataset.id;

      // 商品情報を取得
      window.aivicApi.list(2).then(products => {
        selectedProduct = products.find(p => p.id === productId);
        if (selectedProduct) {
          // 商品の基本情報を設定
          leadTime.value = selectedProduct.リードタイム日数 || 7;
        }
      });
    }
  });

  // スライダーの値表示更新
  weatherImpact.addEventListener('input', (e) => {
    container.querySelector('#weather-impact-value').textContent = `${e.target.value}%`;
  });

  eventImpact.addEventListener('input', (e) => {
    container.querySelector('#event-impact-value').textContent = `${e.target.value}%`;
  });

  // 手動調整の値変更時
  manualAdjustment.addEventListener('input', updateFinalQuantity);

  // 発注書作成
  container.querySelector('#btn-create-order').addEventListener('click', () => {
    if (calculationResult && selectedProduct) {
      window.showScreen('scr-1778591907544'); // 発注書作成画面
    }
  });

  // 計算結果保存
  container.querySelector('#btn-save-calculation').addEventListener('click', async () => {
    if (!calculationResult || !selectedProduct) {
      showError('計算結果がありません');
      return;
    }

    const finalQty = parseInt(manualAdjustment.value) || calculationResult.推奨発注量;

    const orderData = {
      店舗ID: storeSelect.value,
      商品ID: selectedProduct.id,
      発注日: new Date().toISOString(),
      納期予定日: new Date(Date.now() + (parseInt(leadTime.value) || 7) * 24 * 60 * 60 * 1000).toISOString(),
      発注数量: finalQty,
      予測数量: calculationResult.調整後需要,
      発注単価: selectedProduct.単価,
      発注金額: finalQty * selectedProduct.単価,
      発注方法: manualAdjustment.value ? 'AI推奨修正' : 'AI推奨採用',
      発注ステータス: '計算済',
      自動発注フラグ: false,
      作成者ID: 'current-user',
      更新者ID: 'current-user'
    };

    const saved = await window.aivicApi.save(7, orderData); // 発注データ
    if (saved) {
      alert('計算結果を保存しました');
    }
  });

  // 初期化
  loadStores();

  // デフォルト値設定
  const today = new Date();
  const nextWeek = new Date(today.getTime() + 7 * 24 * 60 * 60 * 1000);
  periodStart.value = today.toISOString().split('T')[0];
  periodEnd.value = nextWeek.toISOString().split('T')[0];
}

function(container, apiUrl, tables) {
  let selectedProducts = [];
  let stores = [];
  let products = [];
  let categories = [];
  let predictions = [];
  let salesHistory = [];

  // 初期データの設定
  function initializeData() {
    stores = tables.find(t => t.tableName === '店舗マスタ')?.records || [];
    products = tables.find(t => t.tableName === '商品マスタ')?.records || [];
    predictions = tables.find(t => t.tableName === '需要予測結果')?.records || [];
    salesHistory = tables.find(t => t.tableName === '売上実績データ')?.records || [];

    // カテゴリ一覧を取得
    categories = [...new Set(products.map(p => p.商品カテゴリID))].filter(Boolean);

    renderStoreOptions();
    renderCategoryOptions();

    // 今日の日付を設定
    const today = new Date().toISOString().split('T')[0];
    container.querySelector('#order-date').value = today;

    // 納期は3日後を初期値に設定
    const deliveryDate = new Date();
    deliveryDate.setDate(deliveryDate.getDate() + 3);
    container.querySelector('#delivery-date').value = deliveryDate.toISOString().split('T')[0];
  }

  // 店舗選択肢を描画
  function renderStoreOptions() {
    const storeSelect = container.querySelector('#store-select');
    storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';
    stores.filter(s => s.有効フラグ).forEach(store => {
      storeSelect.innerHTML += `<option value="${store.店舗ID}">${store.店舗名}</option>`;
    });
  }

  // カテゴリ選択肢を描画
  function renderCategoryOptions() {
    const categorySelect = container.querySelector('#category-select');
    categorySelect.innerHTML = '<option value="">全カテゴリ</option>';
    categories.forEach(categoryId => {
      categorySelect.innerHTML += `<option value="${categoryId}">カテゴリ${categoryId}</option>`;
    });
  }

  // 商品一覧を描画
  function renderProductList(productList) {
    const tbody = container.querySelector('#product-list');
    tbody.innerHTML = productList.map(product => {
      const prediction = predictions.find(p => p.商品ID === product.商品ID && p.店舗ID === container.querySelector('#store-select').value);
      const predictedQty = prediction ? prediction.予測数量 : 0;
      const isSelected = selectedProducts.some(p => p.商品ID === product.商品ID);

      return `
        <tr data-id="${product.商品ID}">
          <td><input type="checkbox" class="product-checkbox" ${isSelected ? 'checked' : ''} data-product-id="${product.商品ID}"></td>
          <td>${product.商品名 || ''}</td>
          <td>${product.商品コード || ''}</td>
          <td>¥${(product.単価 || 0).toLocaleString()}</td>
          <td>${predictedQty}</td>
          <td>100</td>
          <td><button class="action-btn secondary add-to-order-btn" data-product-id="${product.商品ID}">追加</button></td>
        </tr>
      `;
    }).join('');
  }

  // 発注商品一覧を描画
  function renderOrderList() {
    const tbody = container.querySelector('#order-list');
    tbody.innerHTML = selectedProducts.map(product => {
      const prediction = predictions.find(p => p.商品ID === product.商品ID && p.店舗ID === container.querySelector('#store-select').value);
      const predictedQty = prediction ? prediction.予測数量 : 0;
      const manualQty = product.手動調整数量 || predictedQty;
      const subtotal = manualQty * (product.単価 || 0);

      return `
        <tr data-id="${product.商品ID}">
          <td>${product.商品名 || ''}</td>
          <td>${product.商品コード || ''}</td>
          <td>¥${(product.単価 || 0).toLocaleString()}</td>
          <td>${predictedQty}</td>
          <td><input type="number" class="input manual-qty-input" value="${manualQty}" min="0" data-product-id="${product.商品ID}"></td>
          <td>¥${subtotal.toLocaleString()}</td>
          <td><button class="action-btn secondary prediction-detail-btn" data-product-id="${product.商品ID}">予測根拠</button></td>
          <td><button class="action-btn secondary remove-btn" data-product-id="${product.商品ID}">削除</button></td>
        </tr>
      `;
    }).join('');

    updateTotalAmount();
  }

  // 発注総額を更新
  function updateTotalAmount() {
    const total = selectedProducts.reduce((sum, product) => {
      const qty = product.手動調整数量 || 0;
      return sum + (qty * (product.単価 || 0));
    }, 0);
    container.querySelector('#total-amount').textContent = `¥${total.toLocaleString()}`;
  }

  // 商品検索
  function searchProducts() {
    const keyword = container.querySelector('#product-search').value.toLowerCase();
    const categoryId = container.querySelector('#category-select').value;

    let filteredProducts = products.filter(p => p.有効フラグ && p.AI予測対象フラグ);

    if (keyword) {
      filteredProducts = filteredProducts.filter(p => 
        (p.商品名 || '').toLowerCase().includes(keyword) || 
        (p.商品コード || '').toLowerCase().includes(keyword)
      );
    }

    if (categoryId) {
      filteredProducts = filteredProducts.filter(p => p.商品カテゴリID === categoryId);
    }

    renderProductList(filteredProducts);
  }

  // 商品を発注リストに追加
  function addToOrder(productId) {
    const product = products.find(p => p.商品ID === productId);
    if (product && !selectedProducts.some(p => p.商品ID === productId)) {
      const prediction = predictions.find(p => p.商品ID === productId && p.店舗ID === container.querySelector('#store-select').value);
      const predictedQty = prediction ? prediction.予測数量 : 1;

      selectedProducts.push({
        ...product,
        手動調整数量: predictedQty
      });
      renderOrderList();
      searchProducts(); // 商品リストを更新
    }
  }

  // 商品を発注リストから削除
  function removeFromOrder(productId) {
    selectedProducts = selectedProducts.filter(p => p.商品ID !== productId);
    renderOrderList();
    searchProducts(); // 商品リストを更新
  }

  // 予測根拠詳細を表示
  function showPredictionDetails(productId) {
    const product = products.find(p => p.商品ID === productId);
    const prediction = predictions.find(p => p.商品ID === productId && p.店舗ID === container.querySelector('#store-select').value);
    const history = salesHistory.filter(s => s.商品ID === productId && s.店舗ID === container.querySelector('#store-select').value).slice(-30);

    const modal = container.querySelector('#prediction-modal');
    const details = container.querySelector('#prediction-details');

    details.innerHTML = `
      <div style="margin-bottom: 16px;">
        <h4>${product?.商品名 || '商品名不明'}</h4>
        <p class="muted">商品コード: ${product?.商品コード || 'N/A'}</p>
      </div>

      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 16px; margin-bottom: 16px;">
        <div class="card">
          <div class="card-body">
            <h5>予測情報</h5>
            <p>予測数量: ${prediction?.予測数量 || 0}個</p>
            <p>予測精度: ${prediction?.予測精度 || 0}%</p>
            <p>推奨発注数量: ${prediction?.推奨発注数量 || 0}個</p>
          </div>
        </div>
        <div class="card">
          <div class="card-body">
            <h5>過去30日の売上実績</h5>
            <p>平均売上数量: ${history.length > 0 ? Math.round(history.reduce((sum, h) => sum + h.販売数量, 0) / history.length) : 0}個/日</p>
            <p>最大売上数量: ${history.length > 0 ? Math.max(...history.map(h => h.販売数量)) : 0}個</p>
            <p>データ件数: ${history.length}件</p>
          </div>
        </div>
      </div>

      <div class="card">
        <div class="card-body">
          <h5>予測要因</h5>
          <ul>
            <li>季節性: ${product?.季節性フラグ ? '季節変動あり' : '季節変動なし'}</li>
            <li>モデルバージョン: ${prediction?.予測モデルバージョン || 'v1.0'}</li>
            <li>予測ステータス: ${prediction?.予測ステータス || '完了'}</li>
          </ul>
        </div>
      </div>
    `;

    modal.classList.remove('hidden');
  }

  // 在庫状況確認を表示
  function showInventoryStatus() {
    const storeId = container.querySelector('#store-select').value;
    if (!storeId) {
      alert('店舗を選択してください');
      return;
    }

    const modal = container.querySelector('#inventory-modal');
    const details = container.querySelector('#inventory-details');

    const inventoryData = selectedProducts.map(product => {
      const prediction = predictions.find(p => p.商品ID === product.商品ID && p.店舗ID === storeId);
      return {
        ...product,
        現在庫: 100, // サンプル値
        安全在庫: 20, // サンプル値
        予測数量: prediction?.予測数量 || 0,
        リードタイム: product.リードタイム日数 || 3
      };
    });

    details.innerHTML = `
      <div class="table-wrap">
        <table>
          <thead>
            <tr>
              <th>商品名</th>
              <th>現在庫</th>
              <th>安全在庫</th>
              <th>予測数量</th>
              <th>リードタイム</th>
              <th>推奨発注数</th>
            </tr>
          </thead>
          <tbody>
            ${inventoryData.map(item => `
              <tr>
                <td>${item.商品名}</td>
                <td>${item.現在庫}</td>
                <td>${item.安全在庫}</td>
                <td>${item.予測数量}</td>
                <td>${item.リードタイム}日</td>
                <td>${Math.max(0, item.予測数量 + item.安全在庫 - item.現在庫)}</td>
              </tr>
            `).join('')}
          </tbody>
        </table>
      </div>
    `;

    modal.classList.remove('hidden');
