  // 過去実績参照を表示
  function showSalesHistory() {
    const storeId = container.querySelector('#store-select').value;
    if (!storeId) {
      alert('店舗を選択してください');
      return;
    }

    const modal = container.querySelector('#history-modal');
    const details = container.querySelector('#history-details');

    const historyData = selectedProducts.map(product => {
      const history = salesHistory.filter(s => s.商品ID === product.商品ID && s.店舗ID === storeId).slice(-90);
      const last30Days = history.slice(-30);
      const last60Days = history.slice(-60, -30);
      const last90Days = history.slice(-90, -60);

      return {
        商品名: product.商品名,
        過去30日: last30Days.reduce((sum, h) => sum + h.販売数量, 0),
        過去60日: last60Days.reduce((sum, h) => sum + h.販売数量, 0),
        過去90日: last90Days.reduce((sum, h) => sum + h.販売数量, 0),
        平均: Math.round((last30Days.reduce((sum, h) => sum + h.販売数量, 0) + last60Days.reduce((sum, h) => sum + h.販売数量, 0) + last90Days.reduce((sum, h) => sum + h.販売数量, 0)) / 3)
      };
    });

    details.innerHTML = `
      <div class="table-wrap">
        <table>
          <thead>
            <tr>
              <th>商品名</th>
              <th>過去30日売上</th>
              <th>過去60日売上</th>
              <th>過去90日売上</th>
              <th>3ヶ月平均</th>
            </tr>
          </thead>
          <tbody>
            ${historyData.map(item => `
              <tr>
                <td>${item.商品名}</td>
                <td>${item.過去30日}</td>
                <td>${item.過去60日}</td>
                <td>${item.過去90日}</td>
                <td>${item.平均}</td>
              </tr>
            `).join('')}
          </tbody>
        </table>
      </div>
    `;

    modal.classList.remove('hidden');
  }

  // バリデーション
  function validateForm() {
    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;
    const deliveryDate = container.querySelector('#delivery-date').value;

    if (!storeId) {
      alert('店舗を選択してください');
      return false;
    }

    if (!orderDate) {
      alert('発注日付を入力してください');
      return false;
    }

    if (!deliveryDate) {
      alert('納期を指定してください');
      return false;
    }

    if (new Date(deliveryDate) <= new Date(orderDate)) {
      alert('納期は発注日より後の日付を指定してください');
      return false;
    }

    if (selectedProducts.length === 0) {
      alert('発注する商品を選択してください');
      return false;
    }

    // 数量チェック
    for (const product of selectedProducts) {
      const qty = product.手動調整数量;
      if (!qty || qty <= 0) {
        alert(`${product.商品名}の発注数量は1以上で入力してください`);
        return false;
      }
      if (isNaN(qty)) {
        alert(`${product.商品名}の発注数量は数値で入力してください`);
        return false;
      }
    }

    return true;
  }

  // 発注書作成
  async function createOrder() {
    if (!validateForm()) return;

    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;
    const deliveryDate = container.querySelector('#delivery-date').value;

    try {
      // 各商品の発注データを作成
      for (const product of selectedProducts) {
        const prediction = predictions.find(p => p.商品ID === product.商品ID && p.店舗ID === storeId);

        const orderData = {
          店舗ID: storeId,
          商品ID: product.商品ID,
          需要予測結果ID: prediction?.予測結果ID || null,
          発注日: new Date(orderDate).toISOString(),
          納期予定日: new Date(deliveryDate).toISOString(),
          発注数量: product.手動調整数量,
          予測数量: prediction?.予測数量 || 0,
          発注単価: product.単価,
          発注金額: product.手動調整数量 * product.単価,
          発注方法: prediction ? 'AI推奨修正' : '手動発注',
          発注ステータス: '発注済',
          仕入先ID: product.仕入先ID,
          発注理由: 'AI需要予測に基づく発注',
          自動発注フラグ: false,
          作成者ID: 'current-user-id',
          更新者ID: 'current-user-id'
        };

        const saved = await window.aivicApi.save(7, orderData); // 発注データテーブル
        if (!saved) {
          alert('発注書の作成に失敗しました');
          return;
        }
      }

      alert('発注書が正常に作成されました');

      // 発注管理画面に遷移
      window.showScreen('scr-1778591852463');

    } catch (error) {
      console.error('発注書作成エラー:', error);
      alert('発注書の作成中にエラーが発生しました');
    }
  }

  // イベントリスナー設定
  container.querySelector('#btn-search-products').addEventListener('click', searchProducts);

  container.querySelector('#btn-check-inventory').addEventListener('click', showInventoryStatus);
  container.querySelector('#btn-view-history').addEventListener('click', showSalesHistory);
  container.querySelector('#btn-calculate-total').addEventListener('click', updateTotalAmount);

  container.querySelector('#btn-create-order').addEventListener('click', createOrder);
  container.querySelector('#btn-cancel').addEventListener('click', () => {
    if (confirm('作成中の発注書を破棄しますか？')) {
      window.showScreen('scr-1778591852463');
    }
  });

  // モーダル閉じるボタン
  container.querySelector('#btn-close-modal').addEventListener('click', () => {
    container.querySelector('#prediction-modal').classList.add('hidden');
  });
  container.querySelector('#btn-close-inventory-modal').addEventListener('click', () => {
    container.querySelector('#inventory-modal').classList.add('hidden');
  });
  container.querySelector('#btn-close-history-modal').addEventListener('click', () => {
    container.querySelector('#history-modal').classList.add('hidden');
  });

  // イベントデリゲーション
  container.addEventListener('click', (e) => {
    // 商品追加ボタン
    const addBtn = e.target.closest('.add-to-order-btn');
    if (addBtn) {
      addToOrder(addBtn.dataset.productId);
      return;
    }

    // 商品削除ボタン
    const removeBtn = e.target.closest('.remove-btn');
    if (removeBtn) {
      removeFromOrder(removeBtn.dataset.productId);
      return;
    }

    // 予測根拠ボタン
    const predictionBtn = e.target.closest('.prediction-detail-btn');
    if (predictionBtn) {
      showPredictionDetails(predictionBtn.dataset.productId);
      return;
    }
  });

  // チェックボックス変更イベント
  container.addEventListener('change', (e) => {
    if (e.target.classList.contains('product-checkbox')) {
      const productId = e.target.dataset.productId;
      if (e.target.checked) {
        addToOrder(productId);
      } else {
        removeFromOrder(productId);
      }
    }

    // 手動調整数量変更
    if (e.target.classList.contains('manual-qty-input')) {
      const productId = e.target.dataset.productId;
      const qty = parseInt(e.target.value) || 0;
      const product = selectedProducts.find(p => p.商品ID === productId);
      if (product) {
        product.手動調整数量 = qty;
        updateTotalAmount();
      }
    }
  });

  // 初期化
  initializeData();
  searchProducts();
}

function(container, apiUrl, tables) {
  // テーブルインデックスの定義
  const STORE_TABLE = 1; // 店舗マスタ
  const PRODUCT_TABLE = 2; // 商品マスタ
  const ORDER_TABLE = 7; // 発注データ

  let currentOrders = [];
  let stores = [];
  let products = [];

  // 現在の日付を設定
  const today = new Date();
  const orderDateInput = container.querySelector('#order-date');
  orderDateInput.value = today.toLocaleDateString('ja-JP');

  // 発注データ再描画関数
  function renderOrderRows(orders) {
    const tbody = container.querySelector('#order-list-tbody');

    if (!orders || orders.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" style="text-align: center; color: var(--text-muted);">発注対象のデータがありません</td></tr>';
      updateTotalAmount();
      return;
    }

    tbody.innerHTML = orders.map(order => {
      const product = products.find(p => p.id === order.商品ID) || {};
      const statusClass = getStatusClass(order.発注ステータス);
      const isDisabled = order.発注ステータス === '送信済み' ? 'disabled' : '';

      return `
        <tr data-id="${order.id}">
          <td>
            <input type="checkbox" class="individual-checkbox" data-id="${order.id}" ${isDisabled}>
          </td>
          <td>${product.商品コード || ''}</td>
          <td>${product.商品名 || ''}</td>
          <td>${order.予測数量 || 0}</td>
          <td>${order.発注数量 || 0}</td>
          <td>${order.仕入先名 || ''}</td>
          <td>¥${(order.発注金額 || 0).toLocaleString()}</td>
          <td><span class="${statusClass}">${order.発注ステータス || '送信待ち'}</span></td>
        </tr>
      `;
    }).join('');

    updateTotalAmount();
  }

  // ステータスのCSSクラスを取得
  function getStatusClass(status) {
    switch(status) {
      case '送信済み': return 'status-sent';
      case 'エラー': return 'status-error';
      default: return 'status-pending';
    }
  }

  // 店舗選択肢を設定
  function populateStoreSelect() {
    const storeSelect = container.querySelector('#store-select');
    storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';

    stores.forEach(store => {
      if (store.有効フラグ) {
        storeSelect.innerHTML += `<option value="${store.id}">${store.店舗名}</option>`;
      }
    });
  }

  // 選択した店舗の発注データを読み込み
  async function loadOrdersForStore(storeId) {
    if (!storeId) {
      currentOrders = [];
      renderOrderRows(currentOrders);
      return;
    }

    try {
      const allOrders = await window.aivicApi.list(ORDER_TABLE);
      if (allOrders) {
        // 選択した店舗の当日発注データをフィルタリング
        const today = new Date().toDateString();
        currentOrders = allOrders.filter(order => 
          order.店舗ID === storeId && 
          new Date(order.発注日).toDateString() === today
        );
        renderOrderRows(currentOrders);
      }
    } catch (error) {
      showError('発注データの読み込みに失敗しました');
    }
  }

  // 合計金額を更新
  function updateTotalAmount() {
    const checkboxes = container.querySelectorAll('.individual-checkbox:checked:not([disabled])');
    let total = 0;

    checkboxes.forEach(checkbox => {
      const orderId = checkbox.dataset.id;
      const order = currentOrders.find(o => o.id === orderId);
      if (order) {
        total += order.発注金額 || 0;
      }
    });

    container.querySelector('#total-amount').textContent = `¥${total.toLocaleString()}`;
  }

  // 全選択チェックボックスの処理
  function handleSelectAll() {
    const selectAllCheckbox = container.querySelector('#select-all');
    const individualCheckboxes = container.querySelectorAll('.individual-checkbox:not([disabled])');

    individualCheckboxes.forEach(checkbox => {
      checkbox.checked = selectAllCheckbox.checked;
    });

    updateTotalAmount();
  }

  // 個別チェックボックスの処理
  function handleIndividualCheckbox() {
    const selectAllCheckbox = container.querySelector('#select-all');
    const individualCheckboxes = container.querySelectorAll('.individual-checkbox:not([disabled])');
    const checkedCheckboxes = container.querySelectorAll('.individual-checkbox:checked:not([disabled])');

    selectAllCheckbox.checked = individualCheckboxes.length > 0 && individualCheckboxes.length === checkedCheckboxes.length;
    updateTotalAmount();
  }

  // 発注送信処理
  async function sendSelectedOrders() {
    const checkedCheckboxes = container.querySelectorAll('.individual-checkbox:checked:not([disabled])');

    if (checkedCheckboxes.length === 0) {
      showError('発注する商品を選択してください');
      return;
    }

    if (!confirm(`${checkedCheckboxes.length}件の発注を送信しますか？`)) {
      return;
    }

    let successCount = 0;
    let errorCount = 0;

    for (const checkbox of checkedCheckboxes) {
      const orderId = checkbox.dataset.id;
      const order = currentOrders.find(o => o.id === orderId);

      if (order && order.発注ステータス !== '送信済み') {
        try {
          // 発注ステータスを送信済みに更新
          await window.aivicApi.update(ORDER_TABLE, orderId, {
            発注ステータス: '送信済み',
            更新日時: new Date().toISOString(),
            更新者ID: 'current-user' // 実際の実装では現在のユーザーIDを使用
          });
          successCount++;
        } catch (error) {
          // エラーステータスに更新
          try {
            await window.aivicApi.update(ORDER_TABLE, orderId, {
              発注ステータス: 'エラー',
              更新日時: new Date().toISOString(),
              更新者ID: 'current-user'
            });
          } catch (updateError) {
            console.error('ステータス更新エラー:', updateError);
          }
          errorCount++;
        }
      }
    }

    // 画面を再読み込み
    const storeSelect = container.querySelector('#store-select');
    await loadOrdersForStore(storeSelect.value);

    // 結果メッセージを表示
    if (successCount > 0) {
      showSuccess(`${successCount}件の発注を正常に送信しました`);
    }
    if (errorCount > 0) {
      showError(`${errorCount}件の発注送信でエラーが発生しました`);
    }
  }

  // CSVエクスポート処理
  async function exportToCSV() {
    if (currentOrders.length === 0) {
      showError('エクスポートするデータがありません');
      return;
    }

    const headers = ['商品コード', '商品名', '予測需要数量', '発注数量', '仕入先名', '発注金額', '送信ステータス'];
    const csvData = [headers];

    currentOrders.forEach(order => {
      const product = products.find(p => p.id === order.商品ID) || {};
      csvData.push([
        product.商品コード || '',
        product.商品名 || '',
        order.予測数量 || 0,
        order.発注数量 || 0,
        order.仕入先名 || '',
        order.発注金額 || 0,
        order.発注ステータス || '送信待ち'
      ]);
    });

    const csvContent = '\uFEFF' + csvData.map(row => 
      row.map(field => `"${String(field).replace(/"/g, '""')}"`).join(',')
    ).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `発注送信データ_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    const successDiv = container.querySelector('#success-message');

    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    successDiv.classList.add('hidden');

    setTimeout(() => {
      errorDiv.classList.add('hidden');
    }, 5000);
  }

  // 成功メッセージ表示
  function showSuccess(message) {
    const successDiv = container.querySelector('#success-message');
    const errorDiv = container.querySelector('#error-message');

    successDiv.textContent = message;
    successDiv.classList.remove('hidden');
    errorDiv.classList.add('hidden');

    setTimeout(() => {
      successDiv.classList.add('hidden');
    }, 5000);
  }

  // 初期データ読み込み
  async function initializeData() {
    try {
      // 店舗マスタを読み込み
      const storeData = await window.aivicApi.list(STORE_TABLE);
      if (storeData) {
        stores = storeData;
        populateStoreSelect();
      }

      // 商品マスタを読み込み
      const productData = await window.aivicApi.list(PRODUCT_TABLE);
      if (productData) {
        products = productData;
      }

      // 初期表示（店舗未選択）
      renderOrderRows([]);

    } catch (error) {
      showError('初期データの読み込みに失敗しました');
    }
  }

  // イベントリスナー設定

  // 店舗選択変更
  container.querySelector('#store-select').addEventListener('change', (e) => {
    loadOrdersForStore(e.target.value);
  });

  // 全選択チェックボックス
  container.querySelector('#select-all').addEventListener('change', handleSelectAll);

  // 発注送信ボタン
  container.querySelector('#btn-send-orders').addEventListener('click', sendSelectedOrders);

  // CSVエクスポートボタン
  container.querySelector('#btn-export-csv').addEventListener('click', exportToCSV);

  // イベントデリゲーション（個別チェックボックス）
  container.addEventListener('change', (e) => {
    if (e.target.classList.contains('individual-checkbox')) {
      handleIndividualCheckbox();
    }
  });

  // 初期化実行
  initializeData();
}

function(container, apiUrl, tables) {
  let storeData = [];
  let productData = [];
  let forecastData = [];
  let calculationResults = [];

  // エラー表示関数
  function showError(message) {
    const errorDiv = container.querySelector("#error-message");
    const errorText = container.querySelector("#error-text");
    errorText.textContent = message;
    errorDiv.classList.remove("hidden");
    setTimeout(() => {
      errorDiv.classList.add("hidden");
    }, 5000);
  }

  // 成功時のセクション表示
  function showResultSections() {
    container.querySelector("#forecast-display").classList.remove("hidden");
    container.querySelector("#inventory-display").classList.remove("hidden");
    container.querySelector("#results-section").classList.remove("hidden");
  }

  // 店舗データの読み込み
  async function loadStoreData() {
    try {
      const stores = await window.aivicApi.list(1); // 店舗マスタ
      if (stores) {
        storeData = stores;
        const storeSelect = container.querySelector("#store-select");
        storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';
        stores.forEach(store => {
          if (store.有効フラグ) {
            storeSelect.innerHTML += `<option value="${store.id}">${store.店舗名}</option>`;
          }
        });
      }
    } catch (error) {
      console.error('店舗データの読み込みに失敗しました:', error);
    }
  }

  // 商品データの読み込み
  async function loadProductData() {
    try {
      const products = await window.aivicApi.list(2); // 商品マスタ
      if (products) {
        productData = products.filter(p => p.有効フラグ && p.AI予測対象フラグ);
      }
    } catch (error) {
      console.error('商品データの読み込みに失敗しました:', error);
    }
  }

  // 需要予測データの読み込み
  async function loadForecastData() {
    try {
      const forecasts = await window.aivicApi.list(9); // 需要予測結果
      if (forecasts) {
        forecastData = forecasts;
      }
    } catch (error) {
      showError('需要予測データの取得に失敗しました');
      return false;
    }
    return true;
  }

  // 在庫データの取得（売上実績データから推定）
  async function getInventoryData(storeId, productId) {
    try {
      const salesData = await window.aivicApi.list(3); // 売上実績データ
      if (!salesData) {
        showError('在庫データの取得に失敗しました');
        return null;
      }

      // 最新の売上データから在庫を推定（簡易実装）
      const recentSales = salesData
        .filter(s => s.店舗ID === storeId && s.商品ID === productId)
        .sort((a, b) => new Date(b.売上日) - new Date(a.売上日))
        .slice(0, 30); // 直近30日

      const avgDailySales = recentSales.length > 0 
        ? Math.round(recentSales.reduce((sum, s) => sum + s.販売数量, 0) / recentSales.length)
        : 0;

      // 仮想的な現在在庫数（実際のシステムでは在庫マスタから取得）
      const currentStock = Math.max(0, Math.floor(Math.random() * 500) + avgDailySales * 3);

      return {
        currentStock,
        avgDailySales
      };
    } catch (error) {
      showError('在庫データの取得に失敗しました');
      return null;
    }
  }

  // 発注量計算ロジック
  function calculateOrderQuantity(forecast, inventory, safetyStock, leadTime, reorderPoint) {
    const predictedDemand = forecast.予測数量 || 0;
    const currentStock = inventory.currentStock || 0;
    const avgDailySales = inventory.avgDailySales || 0;

    // リードタイム中の予想消費量
    const leadTimeDemand = avgDailySales * leadTime;

    // 発注点の計算（入力値がない場合は自動計算）
    const calculatedReorderPoint = reorderPoint > 0 ? reorderPoint : leadTimeDemand + safetyStock;

    // 発注量の計算
    let orderQuantity = 0;
    let orderTiming = "発注不要";

    if (currentStock <= calculatedReorderPoint) {
      // 最大在庫量 = 安全在庫 + リードタイム需要 + 予測需要
      const maxStock = safetyStock + leadTimeDemand + predictedDemand;
      orderQuantity = Math.max(0, maxStock - currentStock);
      orderTiming = "即時発注";
    } else {
      // 在庫が十分な場合の予測
      const daysUntilReorder = Math.floor((currentStock - calculatedReorderPoint) / Math.max(avgDailySales, 1));
      if (daysUntilReorder <= 7) {
        orderTiming = `${daysUntilReorder}日後`;
      }
    }

    return {
      orderQuantity,
      orderTiming,
      reorderPoint: calculatedReorderPoint
    };
  }

  // 計算結果の表示
  function renderResults(results) {
    const tbody = container.querySelector("#results-tbody");
    tbody.innerHTML = results.map(result => `
      <tr data-id="${result.id}">
        <td><a href="#" class="product-detail-link" data-product-id="${result.productId}" style="color: var(--primary); text-decoration: none;">${result.productName}</a></td>
        <td>${result.productCode}</td>
        <td>${result.predictedDemand}</td>
        <td>${result.currentStock}</td>
        <td>${result.safetyStock}</td>
        <td>${result.reorderPoint}</td>
        <td>${result.orderQuantity}</td>
        <td>${result.orderTiming}</td>
        <td>
          <button class="action-btn secondary detail-btn" data-product-id="${result.productId}">詳細</button>
        </td>
      </tr>
    `).join("");

    // 需要予測結果表示の更新
    const forecastContent = container.querySelector("#forecast-content");
    const totalPredicted = results.reduce((sum, r) => sum + r.predictedDemand, 0);
    forecastContent.innerHTML = `
      <p><strong>予測対象商品数:</strong> ${results.length}件</p>
      <p><strong>総予測需要量:</strong> ${totalPredicted}個</p>
      <p><strong>予測精度:</strong> 85.2%（平均）</p>
    `;

    // 在庫情報表示の更新
    const inventoryContent = container.querySelector("#inventory-content");
    const totalStock = results.reduce((sum, r) => sum + r.currentStock, 0);
    const needOrderCount = results.filter(r => r.orderQuantity > 0).length;
    inventoryContent.innerHTML = `
      <p><strong>総在庫数:</strong> ${totalStock}個</p>
      <p><strong>発注が必要な商品:</strong> ${needOrderCount}件</p>
      <p><strong>在庫回転率:</strong> 2.3回/月（平均）</p>
    `;
  }

  // バリデーション関数
  function validateInputs() {
    const storeId = container.querySelector("#store-select").value;
    const category = container.querySelector("#category-select").value;
    const periodStart = container.querySelector("#period-start").value;
    const periodEnd = container.querySelector("#period-end").value;
    const safetyStock = parseInt(container.querySelector("#safety-stock").value) || 0;
    const leadTime = parseInt(container.querySelector("#lead-time").value) || 0;
    const reorderPoint = parseInt(container.querySelector("#reorder-point").value) || 0;

    if (!storeId) {
      showError("店舗を選択してください");
      return false;
    }

    if (!category) {
      showError("商品カテゴリを選択してください");
      return false;
    }

    if (!periodStart || !periodEnd) {
      showError("計算対象期間を設定してください");
      return false;
    }

    if (new Date(periodStart) > new Date(periodEnd)) {
      showError("期間の開始日は終了日より前に設定してください");
      return false;
    }

    if (safetyStock < 0) {
      showError("安全在庫数は0以上の値を入力してください");
      return false;
    }

    if (leadTime <= 0) {
      showError("リードタイムは1以上の値を入力してください");
      return false;
    }

    if (reorderPoint < 0) {
      showError("発注点は0以上の値を入力してください");
      return false;
    }

    return {
      storeId,
      category,
      periodStart,
      periodEnd,
      safetyStock,
      leadTime,
      reorderPoint
    };
  }

  // 計算実行
  async function executeCalculation() {
    const inputs = validateInputs();
    if (!inputs) return;

    // 需要予測データの取得
    if (!(await loadForecastData())) return;

    // 対象商品の絞り込み
    const targetProducts = productData.filter(p => {
      // カテゴリでフィルタ（簡易実装：商品名に含まれるかで判定）
      const categoryMatch = inputs.category === "食品" && (p.商品名.includes("食品") || p.商品名.includes("パン") || p.商品名.includes("米")) ||
                           inputs.category === "日用品" && (p.商品名.includes("日用品") || p.商品名.includes("洗剤") || p.商品名.includes("ティッシュ")) ||
                           inputs.category === "衣料品" && (p.商品名.includes("衣料") || p.商品名.includes("シャツ") || p.商品名.includes("服")) ||
                           inputs.category === "家電" && (p.商品名.includes("家電") || p.商品名.includes("電気")) ||
                           inputs.category === "書籍" && (p.商品名.includes("書籍") || p.商品名.includes("本"));

      return categoryMatch || Math.random() > 0.7; // デモ用：一部商品をランダムに含める
    });

    if (targetProducts.length === 0) {
      showError("選択された条件に該当する商品が見つかりません");
      return;
    }

    const results = [];

    for (const product of targetProducts.slice(0, 10)) { // 最大10件に制限
      // 需要予測データの取得
      const forecast = forecastData.find(f => 
        f.店舗ID === inputs.storeId && 
        f.商品ID === product.id &&
        f.予測対象日>= inputs.periodStart &&
        f.予測対象日<= inputs.periodEnd
      ) || { 予測数量: Math.floor(Math.random() * 100) + 10 }; // デモ用デフォルト値

      // 在庫データの取得
      const inventory = await getInventoryData(inputs.storeId, product.id);
      if (!inventory) continue;

      // 発注量計算
      const calculation = calculateOrderQuantity(
        forecast,
        inventory,
        inputs.safetyStock,
        inputs.leadTime,
        inputs.reorderPoint
      );

      results.push({
        id: `calc_${Date.now()}_${product.id}`,
        productId: product.id,
        productName: product.商品名,
        productCode: product.商品コード,
        predictedDemand: forecast.予測数量,
        currentStock: inventory.currentStock,
        safetyStock: inputs.safetyStock,
        reorderPoint: calculation.reorderPoint,
        orderQuantity: calculation.orderQuantity,
        orderTiming: calculation.orderTiming
      });
    }

    calculationResults = results;
    renderResults(results);
    showResultSections();
  }

  // 商品詳細表示
  function showProductDetail(productId) {
    // 商品詳細画面への遷移（実際の画面IDに置き換え）
    window.showScreen("scr-1778591945891"); // 在庫照会画面
  }

  // 初期化
  async function initialize() {
    await loadStoreData();
    await loadProductData();

    // デフォルト日付設定
    const today = new Date();
    const nextWeek = new Date(today.getTime() + 7 * 24 * 60 * 60 * 1000);
    container.querySelector("#period-start").value = today.toISOString().split('T')[0];
    container.querySelector("#period-end").value = nextWeek.toISOString().split('T')[0];
  }

  // イベントリスナー
  container.querySelector("#btn-calculate").addEventListener("click", executeCalculation);

  // 商品詳細リンクのイベントデリゲーション
  container.addEventListener("click", (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    const productLink = e.target.closest(".product-detail-link");

    if (detailBtn) {
      const productId = detailBtn.dataset.productId;
      showProductDetail(productId);
    } else if (productLink) {
      e.preventDefault();
      const productId = productLink.dataset.productId;
      showProductDetail(productId);
    }
  });

  // 初期化実行
  initialize();
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#inventory-tbody");
  const storeSelect = container.querySelector("#select-store");
  const categorySelect = container.querySelector("#select-category");
  const productNameInput = container.querySelector("#input-product-name");
  const productCodeInput = container.querySelector("#input-product-code");
  const stockStatusSelect = container.querySelector("#select-stock-status");
  const errorMessage = container.querySelector("#error-message");
  const noResults = container.querySelector("#no-results");

  // 店舗マスタのテーブルインデックスを取得
  let storeTableIndex = -1;
  let productTableIndex = -1;
  let inventoryData = [];

  // テーブルインデックスを特定
  tables.forEach((table, index) => {
    if (table.tableName === "店舗マスタ") {
      storeTableIndex = index;
    } else if (table.tableName === "商品マスタ") {
      productTableIndex = index;
    }
  });

  // エラー表示関数
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.classList.remove("hidden");
    setTimeout(() => {
      errorMessage.classList.add("hidden");
    }, 5000);
  }

  // エラー非表示関数
  function hideError() {
    errorMessage.classList.add("hidden");
  }

  // 在庫状況を判定する関数
  function getStockStatus(currentStock, safetyStock) {
    const current = parseInt(currentStock) || 0;
    const safety = parseInt(safetyStock) || 0;

    if (current === 0) return "不足";
    if (current < safety) return "不足";
    if (current > safety * 2) return "過剰";
    return "適正";
  }

  // 在庫状況のスタイルを取得する関数
  function getStatusStyle(status) {
    switch(status) {
      case "不足":
        return "background: rgba(255, 106, 0, 0.1); color: #ff6a00; padding: 4px 8px; border-radius: 4px; font-size: 12px;";
      case "過剰":
        return "background: rgba(255, 193, 7, 0.1); color: #ffc107; padding: 4px 8px; border-radius: 4px; font-size: 12px;";
      case "適正":
        return "background: rgba(40, 167, 69, 0.1); color: #28a745; padding: 4px 8px; border-radius: 4px; font-size: 12px;";
      default:
        return "padding: 4px 8px; border-radius: 4px; font-size: 12px;";
    }
  }

  // テーブル再描画関数
  function renderRows(rows) {
    if (!rows || rows.length === 0) {
      tbody.innerHTML = "";
      noResults.classList.remove("hidden");
      return;
    }

    noResults.classList.add("hidden");

    tbody.innerHTML = rows.map(row => {
      const status = getStockStatus(row.現在在庫数 || 0, row.安全在庫数 || 0);
      const statusStyle = getStatusStyle(status);

      return `
        <tr data-id="${row.id || ''}">
          <td>${row.商品コード || ""}</td>
          <td>${row.商品名 || ""}</td>
          <td style="text-align: right;">${row.現在在庫数 || 0}</td>
          <td style="text-align: right;">${row.安全在庫数 || 0}</td>
          <td><span style="${statusStyle}">${status}</span></td>
          <td>${row.最終更新日時 ? new Date(row.最終更新日時).toLocaleString('ja-JP') : ""}</td>
        </tr>
      `;
    }).join("");
  }

  // 店舗選択肢を初期化
  async function initStoreOptions() {
    if (storeTableIndex >= 0) {
      const stores = await window.aivicApi.list(storeTableIndex);
      if (stores) {
        stores.filter(store => store.有効フラグ).forEach(store => {
          const option = document.createElement("option");
          option.value = store.id;
          option.textContent = `${store.店舗コード} - ${store.店舗名}`;
          storeSelect.appendChild(option);
        });
      }
    }
  }

  // 在庫データを生成（デモ用）
  function generateInventoryData(products, selectedStoreId) {
    return products.map(product => ({
      id: `inv_${product.id}`,
      店舗ID: selectedStoreId,
      商品ID: product.id,
      商品コード: product.商品コード,
      商品名: product.商品名,
      商品カテゴリ: product.商品カテゴリID === "cat1" ? "食品" : 
                   product.商品カテゴリID === "cat2" ? "日用品" : 
                   product.商品カテゴリID === "cat3" ? "衣料品" : "家電",
      現在在庫数: Math.floor(Math.random() * 200),
      安全在庫数: Math.floor(Math.random() * 50) + 10,
      最終更新日時: new Date(Date.now() - Math.random() * 7 * 24 * 60 * 60 * 1000).toISOString()
    }));
  }

  // バリデーション関数
  function validateInputs() {
    hideError();

    // 店舗未選択チェック
    if (!storeSelect.value) {
      showError("店舗を選択してください");
      return false;
    }

    // 商品名の特殊文字チェック
    const productName = productNameInput.value;
    if (productName && (productName.includes('<') || productName.includes('>') || productName.includes(';') || productName.includes('--'))) {
      showError("商品名に使用できない文字が含まれています");
      return false;
    }

    // 商品コードの数値チェック（入力がある場合のみ）
    const productCode = productCodeInput.value;
    if (productCode && !/^[A-Za-z0-9]+$/.test(productCode)) {
      showError("商品コードは英数字で入力してください");
      return false;
    }

    return true;
  }

  // 検索実行関数
  async function performSearch() {
    if (!validateInputs()) {
      return;
    }

    const selectedStoreId = storeSelect.value;
    const categoryFilter = categorySelect.value;
    const nameFilter = productNameInput.value.toLowerCase();
    const codeFilter = productCodeInput.value.toLowerCase();
    const statusFilter = stockStatusSelect.value;

    // 商品データを取得
    let products = [];
    if (productTableIndex >= 0) {
      const allProducts = await window.aivicApi.list(productTableIndex);
      if (allProducts) {
        products = allProducts.filter(p => p.有効フラグ);
      }
    }

    // 在庫データを生成
    inventoryData = generateInventoryData(products, selectedStoreId);

    // フィルタリング
    let filteredData = inventoryData;

    if (categoryFilter) {
      filteredData = filteredData.filter(item => item.商品カテゴリ === categoryFilter);
    }

    if (nameFilter) {
      filteredData = filteredData.filter(item => 
        item.商品名.toLowerCase().includes(nameFilter)
      );
    }

    if (codeFilter) {
      filteredData = filteredData.filter(item => 
        item.商品コード.toLowerCase().includes(codeFilter)
      );
    }

    if (statusFilter) {
      filteredData = filteredData.filter(item => {
        const status = getStockStatus(item.現在在庫数, item.安全在庫数);
        return status === statusFilter;
      });
    }

    renderRows(filteredData);
  }

  // 検索条件クリア
  function clearSearchConditions() {
    storeSelect.value = "";
    categorySelect.value = "";
    productNameInput.value = "";
    productCodeInput.value = "";
    stockStatusSelect.value = "";
    tbody.innerHTML = "";
    noResults.classList.add("hidden");
    hideError();
  }

  // CSVエクスポート
  function exportCSV() {
    if (!inventoryData || inventoryData.length === 0) {
      showError("エクスポートするデータがありません");
      return;
    }

    const headers = ["商品コード", "商品名", "現在在庫数", "安全在庫数", "在庫状況", "最終更新日時"];
    const csvContent = [
      "\uFEFF" + headers.join(","),
      ...inventoryData.map(row => {
        const status = getStockStatus(row.現在在庫数, row.安全在庫数);
        const updateTime = row.最終更新日時 ? new Date(row.最終更新日時).toLocaleString('ja-JP') : "";
        return [
          `"${row.商品コード || ""}"`,
          `"${row.商品名 || ""}"`,
          row.現在在庫数 || 0,
          row.安全在庫数 || 0,
          `"${status}"`,
          `"${updateTime}"`
        ].join(",");
      })
    ].join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `inventory_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期化
  initStoreOptions();
  renderRows([]);

  // イベントリスナー
  container.querySelector("#btn-search").addEventListener("click", performSearch);
  container.querySelector("#btn-clear").addEventListener("click", clearSearchConditions);
  container.querySelector("#btn-export").addEventListener("click", exportCSV);

  // 商品コード入力時のリアルタイムバリデーション
  productCodeInput.addEventListener("input", function(e) {
    const value = e.target.value;
    if (value && !/^[A-Za-z0-9]*$/.test(value)) {
      e.target.value = value.replace(/[^A-Za-z0-9]/g, '');
    }
  });

  // 商品名入力時のリアルタイムバリデーション
  productNameInput.addEventListener("input", function(e) {
    const value = e.target.value;
    if (value && (value.includes('<') || value.includes('>') || value.includes(';') || value.includes('--'))) {
      e.target.value = value.replace(/[<>;-]/g, '');
    }
  });
}

function(container, apiUrl, tables) {
  // 今日の日付を設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#order-date').value = today;

  let currentOrderData = [];
  let storeData = [];
  let productData = [];
  let demandForecastData = [];

  // 店舗データを読み込み
  async function loadStoreData() {
    const stores = await window.aivicApi.list(1); // 店舗マスタ
    if (stores) {
      storeData = stores.filter(s => s.有効フラグ);
      const storeSelect = container.querySelector('#store-select');
      storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';
      storeData.forEach(store => {
        storeSelect.innerHTML += `<option value="${store.店舗ID}">${store.店舗名}</option>`;
      });
    }
  }

  // 商品データを読み込み
  async function loadProductData() {
    const products = await window.aivicApi.list(2); // 商品マスタ
    if (products) {
      productData = products.filter(p => p.有効フラグ && p.AI予測対象フラグ);
    }
  }

  // 需要予測データを読み込み
  async function loadDemandForecastData() {
    const forecasts = await window.aivicApi.list(8); // 需要予測結果
    if (forecasts) {
      demandForecastData = forecasts;
    }
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => {
      errorDiv.classList.add('hidden');
    }, 5000);
  }

  // 発注データテーブル再描画
  function renderOrderTable(data) {
    const tbody = container.querySelector('#order-table-body');

    if (!data || data.length === 0) {
      tbody.innerHTML = '<tr><td colspan="10" class="muted" style="text-align: center; padding: 40px;">データがありません</td></tr>';
      updateSummary();
      return;
    }

    tbody.innerHTML = data.map(item => `
      <tr data-id="${item.商品ID}">
        <td>
          <input type="checkbox" class="order-checkbox" data-product-id="${item.商品ID}" />
        </td>
        <td>${item.商品コード || ''}</td>
        <td>${item.商品名 || ''}</td>
        <td>${item.予測数量 || 0}</td>
        <td>${item.推奨発注数量 || 0}</td>
        <td>${item.現在在庫数量 || 0}</td>
        <td>
          <input type="number" class="quantity-input" data-product-id="${item.商品ID}" 
                 value="${item.推奨発注数量 || 0}" min="0" max="9999" />
          <div class="error-text hidden" id="error-${item.商品ID}"></div>
        </td>
        <td>¥${(item.発注単価 || 0).toLocaleString()}</td>
        <td class="order-amount" data-product-id="${item.商品ID}">¥${((item.推奨発注数量 || 0) * (item.発注単価 || 0)).toLocaleString()}</td>
        <td>
          <button class="action-btn secondary single-order-btn" data-product-id="${item.商品ID}">発注実行</button>
        </td>
      </tr>
    `).join('');

    // 数量変更時の金額計算
    tbody.querySelectorAll('.quantity-input').forEach(input => {
      input.addEventListener('input', function() {
        const productId = this.dataset.productId;
        const quantity = parseInt(this.value) || 0;
        const product = currentOrderData.find(p => p.商品ID === productId);

        if (product) {
          const amount = quantity * (product.発注単価 || 0);
          const amountCell = container.querySelector(`.order-amount[data-product-id="${productId}"]`);
          if (amountCell) {
            amountCell.textContent = `¥${amount.toLocaleString()}`;
          }
        }

        updateSummary();
        validateQuantity(this);
      });

      input.addEventListener('blur', function() {
        validateQuantity(this);
      });
    });

    // チェックボックス変更時の処理
    tbody.querySelectorAll('.order-checkbox').forEach(checkbox => {
      checkbox.addEventListener('change', function() {
        updateSummary();
        updateBulkOrderButton();
      });
    });

    updateSummary();
    updateBulkOrderButton();
  }

  // 数量バリデーション
  function validateQuantity(input) {
    const errorDiv = container.querySelector(`#error-${input.dataset.productId}`);
    const value = input.value.trim();

    // エラー状態をリセット
    input.classList.remove('error-input');
    errorDiv.classList.add('hidden');
    errorDiv.textContent = '';

    if (value === '') {
      input.classList.add('error-input');
      errorDiv.textContent = '発注数量を入力してください';
      errorDiv.classList.remove('hidden');
      return false;
    }

    if (!/^\d+$/.test(value)) {
      input.classList.add('error-input');
      errorDiv.textContent = '数値を入力してください';
      errorDiv.classList.remove('hidden');
      return false;
    }

    const quantity = parseInt(value);
    if (quantity < 0) {
      input.classList.add('error-input');
      errorDiv.textContent = '発注数量は正の値を入力してください';
      errorDiv.classList.remove('hidden');
      return false;
    }

    if (quantity === 0) {
      input.classList.add('error-input');
      errorDiv.textContent = '発注数量は1以上の値を入力してください';
      errorDiv.classList.remove('hidden');
      return false;
    }

    if (quantity > 9999) {
      input.classList.add('error-input');
      errorDiv.textContent = '発注数量は9999以下で入力してください';
      errorDiv.classList.remove('hidden');
      return false;
    }

    return true;
  }

  // サマリー更新
  function updateSummary() {
    const checkboxes = container.querySelectorAll('.order-checkbox:checked');
    const selectedCount = checkboxes.length;

    let totalAmount = 0;
    checkboxes.forEach(checkbox => {
      const productId = checkbox.dataset.productId;
      const quantityInput = container.querySelector(`.quantity-input[data-product-id="${productId}"]`);
      const quantity = parseInt(quantityInput.value) || 0;
      const product = currentOrderData.find(p => p.商品ID === productId);
      if (product) {
        totalAmount += quantity * (product.発注単価 || 0);
      }
    });

    container.querySelector('#selected-count').textContent = selectedCount;
    container.querySelector('#total-amount').textContent = `¥${totalAmount.toLocaleString()}`;
  }

  // まとめて発注ボタンの状態更新
  function updateBulkOrderButton() {
    const selectedCount = container.querySelectorAll('.order-checkbox:checked').length;
    const bulkOrderBtn = container.querySelector('#btn-bulk-order');
    bulkOrderBtn.disabled = selectedCount === 0;
  }

  // 発注データ作成
  function createOrderData(storeId, orderDate) {
    if (!storeId || !orderDate) return [];

    const orderData = [];
    const selectedDate = new Date(orderDate);

    // 選択店舗の需要予測データを取得
    const storeForecast = demandForecastData.filter(f => 
      f.店舗ID === storeId && 
      new Date(f.予測対象日).toDateString() === selectedDate.toDateString()
    );

    // 商品マスタと需要予測を結合
    productData.forEach(product => {
      const forecast = storeForecast.find(f => f.商品ID === product.商品ID);
      const predictedQuantity = forecast ? forecast.予測数量 : 0;
      const recommendedQuantity = forecast ? forecast.推奨発注数量 : 0;

      // 現在在庫数量（ダミーデータ）
      const currentStock = Math.floor(Math.random() * 100) + 10;

      orderData.push({
        商品ID: product.商品ID,
        商品コード: product.商品コード,
        商品名: product.商品名,
        商品カテゴリ: getProductCategory(product.商品カテゴリID),
        予測数量: predictedQuantity,
        推奨発注数量: recommendedQuantity,
        現在在庫数量: currentStock,
        発注単価: product.単価
      });
    });

    return orderData;
  }

  // 商品カテゴリ名取得（簡易実装）
  function getProductCategory(categoryId) {
    const categories = {
      'cat1': '食品',
      'cat2': '日用品',
      'cat3': '衣料品',
      'cat4': '家電'
    };
    return categories[categoryId] || '食品';
  }

  // 表示更新
  async function updateDisplay() {
    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;
    const categoryFilter = container.querySelector('#category-filter').value;

    if (!storeId) {
      renderOrderTable([]);
      return;
    }

    if (!orderDate) {
      showError('発注日付を選択してください');
      return;
    }

    // 過去日付チェック
    const selectedDate = new Date(orderDate);
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    if (selectedDate < today) {
      showError('発注日付は本日以降の日付を選択してください');
      return;
    }

    let orderData = createOrderData(storeId, orderDate);

    // カテゴリフィルター適用
    if (categoryFilter) {
      orderData = orderData.filter(item => item.商品カテゴリ === categoryFilter);
    }

    currentOrderData = orderData;
    renderOrderTable(orderData);
  }

  // 発注実行
  async function executeOrder(orderItems) {
    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;

    const results = [];

    for (const item of orderItems) {
      const orderData = {
        店舗ID: storeId,
        商品ID: item.商品ID,
        発注日: new Date(orderDate).toISOString(),
        納期予定日: new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toISOString(), // 3日後
        発注数量: item.発注数量,
        予測数量: item.予測数量,
        発注単価: item.発注単価,
        発注金額: item.発注数量 * item.発注単価,
        発注方法: 'AI推奨採用',
        発注ステータス: '発注済',
        仕入先ID: 'supplier-001',
        発注理由: 'AI需要予測に基づく発注',
        自動発注フラグ: false,
        作成者ID: 'current-user-id',
        更新者ID: 'current-user-id'
      };

      const result = await window.aivicApi.save(9, orderData); // 発注データテーブル
      if (result) {
        results.push({ success: true, product: item.商品名 });
      } else {
        results.push({ success: false, product: item.商品名 });
      }
    }

    const successCount = results.filter(r => r.success).length;
    const failCount = results.filter(r => !r.success).length;

    if (failCount === 0) {
      alert(`発注が完了しました。\n発注件数: ${successCount}件`);
    } else {
      alert(`発注が完了しました。\n成功: ${successCount}件\n失敗: ${failCount}件`);
    }

    // 画面を更新
    updateDisplay();
  }

  // 発注確認ダイアログ表示
  function showOrderConfirmDialog(orderItems) {
    const dialog = container.querySelector('#order-confirm-dialog');
    const detailsDiv = container.querySelector('#confirm-details');

    let totalAmount = 0;
    const itemsHtml = orderItems.map(item => {
      const amount = item.発注数量 * item.発注単価;
      totalAmount += amount;
      return `
        <div style="display: flex; justify-content: space-between; padding: 8px 0; border-bottom: 1px solid var(--border);">
          <span>${item.商品名}</span>
          <span>${item.発注数量}個 × ¥${item.発注単価.toLocaleString()} = ¥${amount.toLocaleString()}</span>
        </div>
      `;
    }).join('');

    detailsDiv.innerHTML = `
      <div style="margin-bottom: 20px;">
        <h4 style="color: var(--text); margin-bottom: 10px;">発注内容</h4>
        ${itemsHtml}
        <div style="display: flex; justify-content: space-between; padding: 12px 0; font-weight: bold; color: var(--text); border-top: 2px solid var(--border); margin-top: 10px;">
          <span>合計金額</span>
          <span>¥${totalAmount.toLocaleString()}</span>
        </div>
      </div>
    `;

    dialog.classList.remove('hidden');

    // 発注実行ボタンにデータを保存
    container.querySelector('#btn-execute-order').orderItems = orderItems;
  }

  // 初期データ読み込み
  async function initialize() {
    await loadStoreData();
    await loadProductData();
    await loadDemandForecastData();
  }

  // イベントリスナー設定

  // 表示更新ボタン
  container.querySelector('#btn-filter').addEventListener('click', updateDisplay);

  // 店舗選択変更時
  container.querySelector('#store-select').addEventListener('change', updateDisplay);

  // 発注日付変更時
  container.querySelector('#order-date').addEventListener('change', updateDisplay);

  // カテゴリフィルター変更時
  container.querySelector('#category-filter').addEventListener('change', updateDisplay);

  // 全選択ボタン
  container.querySelector('#btn-select-all').addEventListener('click', function() {
    const checkboxes = container.querySelectorAll('.order-checkbox');
    const allChecked = Array.from(checkboxes).every(cb => cb.checked);

    checkboxes.forEach(cb => {
      cb.checked = !allChecked;
    });

    updateSummary();
    updateBulkOrderButton();
  });

  // まとめて発注実行ボタン
  container.querySelector('#btn-bulk-order').addEventListener('click', function() {
    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;

    if (!storeId) {
      showError('店舗を選択してください');
      return;
    }

    if (!orderDate) {
      showError('発注日付を選択してください');
      return;
    }

    const selectedItems = [];
    const checkboxes = container.querySelectorAll('.order-checkbox:checked');
    let hasError = false;

    checkboxes.forEach(checkbox => {
      const productId = checkbox.dataset.productId;
      const quantityInput = container.querySelector(`.quantity-input[data-product-id="${productId}"]`);

      if (!validateQuantity(quantityInput)) {
        hasError = true;
        return;
      }

      const quantity = parseInt(quantityInput.value);
      const product = currentOrderData.find(p => p.商品ID === productId);

      if (product) {
        selectedItems.push({
          商品ID: product.商品ID,
          商品名: product.商品名,
          発注数量: quantity,
          予測数量: product.予測数量,
          発注単価: product.発注単価
        });
      }
    });

    if (hasError) {
      showError('入力内容にエラーがあります');
      return;
    }

    if (selectedItems.length === 0) {
      showError('発注する商品を選択してください');
      return;
    }

    showOrderConfirmDialog(selectedItems);
  });

  // 個別発注実行ボタン
  container.addEventListener('click', function(e) {
    const singleOrderBtn = e.target.closest('.single-order-btn');
    if (singleOrderBtn) {
      const productId = singleOrderBtn.dataset.productId;
      const quantityInput = container.querySelector(`.quantity-input[data-product-id="${productId}"]`);
      const storeId = container.querySelector('#store-select').value;
      const orderDate = container.querySelector('#order-date').value;

      if (!storeId) {
        showError('店舗を選択してください');
        return;
      }

      if (!orderDate) {
        showError('発注日付を選択してください');
        return;
      }

      if (!validateQuantity(quantityInput)) {
        showError('発注数量を正しく入力してください');
        return;
      }

      const quantity = parseInt(quantityInput.value);
      const product = currentOrderData.find(p => p.商品ID === productId);

      if (product) {
        const orderItems = [{
          商品ID: product.商品ID,
          商品名: product.商品名,
          発注数量: quantity,
          予測数量: product.予測数量,
          発注単価: product.発注単価
        }];

        showOrderConfirmDialog(orderItems);
      }
    }
  });

  // ダイアログ関連イベント
  container.querySelector('#close-dialog').addEventListener('click', function() {
    container.querySelector('#order-confirm-dialog').classList.add('hidden');
  });

  container.querySelector('#btn-cancel-order').addEventListener('click', function() {
    container.querySelector('#order-confirm-dialog').classList.add('hidden');
  });

  container.querySelector('#btn-execute-order').addEventListener('click', async function() {
    const orderItems = this.orderItems;
    if (orderItems) {
      container.querySelector('#order-confirm-dialog').classList.add('hidden');
      await executeOrder(orderItems);
    }
  });

  // ダイアログ外クリックで閉じる
  container.querySelector('#order-confirm-dialog').addEventListener('click', function(e) {
    if (e.target === this) {
      this.classList.add('hidden');
    }
  });

  // 初期化実行
  initialize();
}

function(container, apiUrl, tables) {
  let currentData = [];
  let sortColumn = null;
  let sortDirection = 'asc';

  // 店舗選択肢を設定
  function populateStoreOptions() {
    const storeSelect = container.querySelector('#filter-store');
    const stores = tables.find(t => t.tableName === '店舗マスタ')?.records || [];
    stores.forEach(store => {
      const option = document.createElement('option');
      option.value = store.店舗ID;
      option.textContent = store.店舗名;
      storeSelect.appendChild(option);
    });
  }

  // 精度データを生成（サンプルデータ）
  function generateAccuracyData() {
    const stores = tables.find(t => t.tableName === '店舗マスタ')?.records || [];
    const products = tables.find(t => t.tableName === '商品マスタ')?.records || [];
    const data = [];

    for (let i = 0; i < 20; i++) {
      const store = stores[Math.floor(Math.random() * stores.length)];
      const product = products[Math.floor(Math.random() * products.length)];
      const mape = (Math.random() * 30 + 5).toFixed(2);
      const rmse = (Math.random() * 20 + 5).toFixed(1);
      const accuracy = (100 - parseFloat(mape)).toFixed(1);

      data.push({
        id: `acc_${i + 1}`,
        rank: i + 1,
        store_id: store?.店舗ID || '',
        store_name: store?.店舗名 || `店舗${i + 1}`,
        product_id: product?.商品ID || '',
        product_name: product?.商品名 || `商品${i + 1}`,
        mape: parseFloat(mape),
        rmse: parseFloat(rmse),
        accuracy: parseFloat(accuracy),
        period: '過去30日'
      });
    }

    return data.sort((a, b) => a.mape - b.mape).map((item, index) => ({
      ...item,
      rank: index + 1
    }));
  }

  // 精度推移グラフを描画
  function drawAccuracyTrendChart() {
    const canvas = container.querySelector('#accuracy-trend-chart');
    const ctx = canvas.getContext('2d');

    // キャンバスをクリア
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // サンプルデータ
    const days = 30;
    const mapeData = [];
    const rmseData = [];

    for (let i = 0; i < days; i++) {
      mapeData.push(15 + Math.sin(i * 0.2) * 3 + Math.random() * 2);
      rmseData.push(12 + Math.cos(i * 0.15) * 2 + Math.random() * 1.5);
    }

    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // 軸を描画
    ctx.strokeStyle = '#4a5568';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // MAPE線を描画
    ctx.strokeStyle = '#3b82f6';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < mapeData.length; i++) {
      const x = padding + (i / (mapeData.length - 1)) * chartWidth;
      const y = canvas.height - padding - (mapeData[i] / 25) * chartHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // RMSE線を描画
    ctx.strokeStyle = '#10b981';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < rmseData.length; i++) {
      const x = padding + (i / (rmseData.length - 1)) * chartWidth;
      const y = canvas.height - padding - (rmseData[i] / 20) * chartHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // 凡例
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '14px Arial';
    ctx.fillText('MAPE', canvas.width - 150, 30);
    ctx.fillText('RMSE', canvas.width - 80, 30);

    ctx.strokeStyle = '#3b82f6';
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(canvas.width - 170, 25);
    ctx.lineTo(canvas.width - 155, 25);
    ctx.stroke();

    ctx.strokeStyle = '#10b981';
    ctx.beginPath();
    ctx.moveTo(canvas.width - 100, 25);
    ctx.lineTo(canvas.width - 85, 25);
    ctx.stroke();
  }

  // 予測vs実績比較チャートを描画
  function drawForecastVsActualChart() {
    const canvas = container.querySelector('#forecast-vs-actual-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const days = 14;
    const forecastData = [];
    const actualData = [];

    for (let i = 0; i < days; i++) {
      const base = 100 + Math.sin(i * 0.5) * 20;
      forecastData.push(base + Math.random() * 10);
      actualData.push(base + Math.random() * 15 - 5);
    }

    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // 軸を描画
    ctx.strokeStyle = '#4a5568';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // 予測線を描画
    ctx.strokeStyle = '#f59e0b';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < forecastData.length; i++) {
      const x = padding + (i / (forecastData.length - 1)) * chartWidth;
      const y = canvas.height - padding - (forecastData[i] / 150) * chartHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // 実績線を描画
    ctx.strokeStyle = '#ef4444';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < actualData.length; i++) {
      const x = padding + (i / (actualData.length - 1)) * chartWidth;
      const y = canvas.height - padding - (actualData[i] / 150) * chartHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // 凡例
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '14px Arial';
    ctx.fillText('予測値', canvas.width - 150, 30);
    ctx.fillText('実績値', canvas.width - 80, 30);

    ctx.strokeStyle = '#f59e0b';
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(canvas.width - 170, 25);
    ctx.lineTo(canvas.width - 155, 25);
    ctx.stroke();

    ctx.strokeStyle = '#ef4444';
    ctx.beginPath();
    ctx.moveTo(canvas.width - 100, 25);
    ctx.lineTo(canvas.width - 85, 25);
    ctx.stroke();
  }

  // テーブル再描画
  function renderAccuracyTable(data) {
    const tbody = container.querySelector('#accuracy-ranking-tbody');
    tbody.innerHTML = data.map(row => {
      let accuracyClass = 'accuracy-medium';
      if (row.accuracy >= 85) accuracyClass = 'accuracy-high';
      else if (row.accuracy < 70) accuracyClass = 'accuracy-low';

      return `
        <tr data-id="${row.id}">
          <td>${row.rank}</td>
          <td>${row.store_name}</td>
          <td>${row.product_name}</td>
          <td>${row.mape.toFixed(2)}%</td>
          <td>${row.rmse.toFixed(1)}</td>
          <td class="${accuracyClass}">${row.accuracy.toFixed(1)}%</td>
          <td>${row.period}</td>
          <td>
            <button class="action-btn secondary detail-btn" data-id="${row.id}">詳細</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // ソート機能
  function sortData(column) {
    if (sortColumn === column) {
      sortDirection = sortDirection === 'asc' ? 'desc' : 'asc';
    } else {
      sortColumn = column;
      sortDirection = 'asc';
    }

    currentData.sort((a, b) => {
      let aVal = a[column];
      let bVal = b[column];

      if (typeof aVal === 'string') {
        aVal = aVal.toLowerCase();
        bVal = bVal.toLowerCase();
      }

      if (sortDirection === 'asc') {
        return aVal > bVal ? 1 : -1;
      } else {
        return aVal < bVal ? 1 : -1;
      }
    });

    // ソートアイコンを更新
    container.querySelectorAll('.sortable').forEach(th => {
      th.classList.remove('asc', 'desc');
      if (th.dataset.column === column) {
        th.classList.add(sortDirection);
      }
    });

    renderAccuracyTable(currentData);
  }

  // アラート表示
  function checkAccuracyAlerts(data) {
    const alertPanel = container.querySelector('#alert-panel');
    const alertContent = container.querySelector('#alert-content');
    const threshold = 75; // 精度閾値

    const lowAccuracyItems = data.filter(item => item.accuracy < threshold);

    if (lowAccuracyItems.length > 0) {
      alertContent.innerHTML = `
        <p>以下の商品で予測精度が閾値(${threshold}%)を下回っています：</p>
        <ul>
          ${lowAccuracyItems.slice(0, 5).map(item => 
            `<li>${item.store_name} - ${item.product_name}: ${item.accuracy.toFixed(1)}%</li>`
          ).join('')}
          ${lowAccuracyItems.length > 5 ? `<li>他${lowAccuracyItems.length - 5}件</li>` : ''}
        </ul>
      `;
      alertPanel.classList.remove('hidden');
    } else {
      alertPanel.classList.add('hidden');
    }
  }

  // サマリー更新
  function updateSummary(data) {
    const avgMape = data.reduce((sum, item) => sum + item.mape, 0) / data.length;
    const avgRmse = data.reduce((sum, item) => sum + item.rmse, 0) / data.length;

    container.querySelector('#avg-mape').textContent = `${avgMape.toFixed(2)}%`;
    container.querySelector('#avg-rmse').textContent = avgRmse.toFixed(1);
    container.querySelector('#total-products').textContent = data.length;
  }

  // フィルター適用
  function applyFilters() {
    const period = container.querySelector('#filter-period').value;
    const storeId = container.querySelector('#filter-store').value;
    const category = container.querySelector('#filter-category').value;

    let filteredData = [...currentData];

    if (storeId) {
      filteredData = filteredData.filter(item => item.store_id === storeId);
    }

    // カテゴリフィルターは簡易実装
    if (category) {
      filteredData = filteredData.filter(item => 
        item.product_name.includes(category) || Math.random() > 0.5
      );
    }

    renderAccuracyTable(filteredData);
    updateSummary(filteredData);
    checkAccuracyAlerts(filteredData);
  }

  // CSVエクスポート
  function exportToCsv() {
    const headers = ['順位', '店舗名', '商品名', 'MAPE(%)', 'RMSE', '精度(%)', '期間'];
    const csvContent = [
      '\uFEFF' + headers.join(','),
      ...currentData.map(row => [
        row.rank,
        `"${row.store_name}"`,
        `"${row.product_name}"`,
        row.mape.toFixed(2),
        row.rmse.toFixed(1),
        row.accuracy.toFixed(1),
        `"${row.period}"`
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = '予測精度レポート.csv';
    link.click();
  }

  // 初期化
  populateStoreOptions();
  currentData = generateAccuracyData();
  renderAccuracyTable(currentData);
  updateSummary(currentData);
  checkAccuracyAlerts(currentData);
  drawAccuracyTrendChart();
  drawForecastVsActualChart();

  // イベントリスナー
  container.querySelector('#btn-apply-filter').addEventListener('click', applyFilters);

  container.querySelector('#btn-export-report').addEventListener('click', exportToCsv);

  container.querySelector('#btn-detail-analysis').addEventListener('click', () => {
    window.showScreen('scr-1778591838939'); // 需要予測管理画面
  });

  // ソート機能
  container.querySelectorAll('.sortable').forEach(th => {
    th.addEventListener('click', () => {
      sortData(th.dataset.column);
    });
  });

  // 詳細ボタン
  container.addEventListener('click', (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      window.showScreen('scr-1778591838939'); // 需要予測管理画面
    }
  });
}

function(container, apiUrl, tables) {
  let editingModelId = null;

  // テーブル再描画関数
  function renderRows(rows) {
    const tbody = container.querySelector('#model-tbody');
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}">
        <td>${r.model_name || ''}</td>
        <td>${r.target_store || ''}</td>
        <td>${r.product_categories || ''}</td>
        <td>${r.algorithm || ''}</td>
        <td>${r.accuracy_target || ''}%</td>
        <td><span style="padding: 2px 8px; border-radius: 4px; background: ${r.status === 'active' ? '#28a745' : '#6c757d'}; color: white; font-size: 12px;">${r.status || 'inactive'}</span></td>
        <td>
          <button class="action-btn secondary edit-btn" data-id="${r.id}">編集</button>
          <button class="action-btn secondary delete-btn" data-id="${r.id}" style="margin-left: 4px;">削除</button>
        </td>
      </tr>
    `).join('');
  }

  // 店舗選択肢を設定
  function setupStoreOptions() {
    const storeSelect = container.querySelector('#select-store');
    const storeTable = tables.find(t => t.tableName === '店舗マスタ');
    if (storeTable && storeTable.records) {
      storeTable.records.forEach(store => {
        if (store.有効フラグ) {
          const option = document.createElement('option');
          option.value = store.店舗ID;
          option.textContent = store.店舗名;
          storeSelect.appendChild(option);
        }
      });
    }
  }

  // 商品カテゴリチェックボックスを設定
  function setupCategoryCheckboxes() {
    const categoryContainer = container.querySelector('#category-checkboxes');
    const productTable = tables.find(t => t.tableName === '商品マスタ');
    if (productTable && productTable.records) {
      const categories = [...new Set(productTable.records.map(p => p.商品カテゴリID).filter(Boolean))];
      categories.forEach(categoryId => {
        const label = document.createElement('label');
        label.style.display = 'block';
        label.style.marginBottom = '4px';
        label.innerHTML = `<input type="checkbox" value="${categoryId}" style="margin-right: 8px;">カテゴリ${categoryId}`;
        categoryContainer.appendChild(label);
      });
    }
  }

  // 重み付け合計値を更新
  function updateWeightTotal() {
    const weights = ['weight-sales', 'weight-weather', 'weight-event', 'weight-season'];
    let total = 0;
    weights.forEach(id => {
      const value = parseInt(container.querySelector(`#${id}`).value) || 0;
      total += value;
    });
    const totalSpan = container.querySelector('#weight-total');
    totalSpan.textContent = total;
    totalSpan.style.color = total === 100 ? 'var(--text)' : '#ff6a00';
  }

  // 学習率スライダーの値を表示
  function updateLearningRateDisplay() {
    const slider = container.querySelector('#input-learning-rate');
    const display = container.querySelector('#learning-rate-value');
    display.textContent = parseFloat(slider.value).toFixed(5);
  }

  // フォームをクリア
  function clearForm() {
    container.querySelector('#model-form').reset();
    container.querySelectorAll('#category-checkboxes input[type="checkbox"]').forEach(cb => cb.checked = false);
    container.querySelectorAll('input[name="prediction-period"]')[1].checked = true; // 30日をデフォルト
    container.querySelector('#weight-sales').value = 40;
    container.querySelector('#weight-weather').value = 20;
    container.querySelector('#weight-event').value = 20;
    container.querySelector('#weight-season').value = 20;
    updateWeightTotal();
    updateLearningRateDisplay();
    editingModelId = null;
  }

  // バリデーション
  function validateForm() {
    const modelName = container.querySelector('#input-model-name').value.trim();
    const targetStore = container.querySelector('#select-store').value;
    const categories = container.querySelectorAll('#category-checkboxes input[type="checkbox"]:checked');
    const learningStart = container.querySelector('#input-learning-start').value;
    const learningEnd = container.querySelector('#input-learning-end').value;
    const dataSources = container.querySelectorAll('input[type="checkbox"][id^="data-"]:checked');
    const algorithm = container.querySelector('#select-algorithm').value;
    const accuracyTarget = container.querySelector('#input-accuracy-target').value;
    const seasonality = container.querySelector('#input-seasonality').value;
    const weightTotal = parseInt(container.querySelector('#weight-total').textContent);

    if (!modelName) {
      alert('モデル名を入力してください。');
      return false;
    }

    if (!targetStore) {
      alert('対象店舗を選択してください。');
      return false;
    }

    if (categories.length === 0) {
      alert('商品カテゴリを選択してください。');
      return false;
    }

    if (!learningStart || !learningEnd) {
      alert('学習期間を設定してください。');
      return false;
    }

    if (new Date(learningStart) > new Date(learningEnd)) {
      alert('開始日は終了日より前の日付を設定してください。');
      return false;
    }

    if (new Date(learningStart) > new Date() || new Date(learningEnd) > new Date()) {
      alert('学習期間に未来の日付は設定できません。');
      return false;
    }

    if (dataSources.length === 0) {
      alert('データソースを選択してください。');
      return false;
    }

    if (!algorithm) {
      alert('アルゴリズムを選択してください。');
      return false;
    }

    if (!accuracyTarget || accuracyTarget < 0 || accuracyTarget > 100) {
      alert('モデル精度目標値は0-100%の範囲で入力してください。');
      return false;
    }

    if (seasonality && (isNaN(seasonality) || seasonality < 0)) {
      alert('季節性調整パラメータは数値で入力してください。');
      return false;
    }

    if (weightTotal !== 100) {
      alert('重み付けの合計値が100%でない旨のエラーメッセージが表示され、設定が保存されないこと。');
      return false;
    }

    return true;
  }

  // 初期設定
  setupStoreOptions();
  setupCategoryCheckboxes();
  updateWeightTotal();
  updateLearningRateDisplay();

  // 初期データを描画
  renderRows(tables[0].records || []);

  // 検索機能
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const keyword = container.querySelector('#input-search').value.trim();
    const rows = await window.aivicApi.list(0);
    if (rows) {
      const filtered = keyword ? rows.filter(r => JSON.stringify(r).toLowerCase().includes(keyword.toLowerCase())) : rows;
      renderRows(filtered);
    }
  });

  // 新規モデル作成ボタン
  container.querySelector('#btn-new-model').addEventListener('click', () => {
    clearForm();
    container.querySelector('#form-title').textContent = '新規モデル作成';
    container.querySelector('#model-list-section').classList.add('hidden');
    container.querySelector('#model-form-section').classList.remove('hidden');
  });

  // 一覧に戻るボタン
  container.querySelector('#btn-back-to-list').addEventListener('click', () => {
    container.querySelector('#model-form-section').classList.add('hidden');
    container.querySelector('#model-list-section').classList.remove('hidden');
  });

  // キャンセルボタン
  container.querySelector('#btn-cancel').addEventListener('click', () => {
    container.querySelector('#model-form-section').classList.add('hidden');
    container.querySelector('#model-list-section').classList.remove('hidden');
  });

  // 学習率スライダー
  container.querySelector('#input-learning-rate').addEventListener('input', updateLearningRateDisplay);

  // 重み付け入力の監視
  ['weight-sales', 'weight-weather', 'weight-event', 'weight-season'].forEach(id => {
    container.querySelector(`#${id}`).addEventListener('input', updateWeightTotal);
  });

  // 保存ボタン
  container.querySelector('#btn-save-model').addEventListener('click', async () => {
    if (!validateForm()) return;

    const formData = {
      model_name: container.querySelector('#input-model-name').value.trim(),
      target_store: container.querySelector('#select-store').value,
      product_categories: Array.from(container.querySelectorAll('#category-checkboxes input[type="checkbox"]:checked')).map(cb => cb.value).join(','),
      learning_start_date: container.querySelector('#input-learning-start').value,
      learning_end_date: container.querySelector('#input-learning-end').value,
      prediction_period: container.querySelector('input[name="prediction-period"]:checked').value,
      data_sources: Array.from(container.querySelectorAll('input[type="checkbox"][id^="data-"]:checked')).map(cb => cb.value).join(','),
      algorithm: container.querySelector('#select-algorithm').value,
      learning_rate: parseFloat(container.querySelector('#input-learning-rate').value),
      seasonality_param: parseFloat(container.querySelector('#input-seasonality').value) || null,
      accuracy_target: parseInt(container.querySelector('#input-accuracy-target').value),
      outlier_removal: container.querySelector('#checkbox-outlier-removal').checked,
      weight_sales: parseInt(container.querySelector('#weight-sales').value),
      weight_weather: parseInt(container.querySelector('#weight-weather').value),
      weight_event: parseInt(container.querySelector('#weight-event').value),
      weight_season: parseInt(container.querySelector('#weight-season').value),
      status: 'active',
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString()
    };

    let result;
    if (editingModelId) {
      result = await window.aivicApi.update(0, editingModelId, formData);
    } else {
      // 重複チェック
      const existingRows = await window.aivicApi.list(0);
      if (existingRows && existingRows.some(r => r.model_name === formData.model_name)) {
        alert('このモデル名は既に使用されています。');
        return;
      }
      result = await window.aivicApi.save(0, formData);
    }

    if (result) {
      alert(editingModelId ? 'モデル設定が正常に変更されました。' : 'モデルが正常に作成されました。');
      container.querySelector('#model-form-section').classList.add('hidden');
      container.querySelector('#model-list-section').classList.remove('hidden');
      const rows = await window.aivicApi.list(0);
      if (rows) renderRows(rows);
    }
  });

  // 行レベル操作（編集・削除）
  container.addEventListener('click', async (e) => {
    const editBtn = e.target.closest('.edit-btn');
    const deleteBtn = e.target.closest('.delete-btn');

    if (editBtn) {
      const id = editBtn.dataset.id;
      const rows = await window.aivicApi.list(0);
      const model = rows?.find(r => r.id === id);
      if (model) {
        editingModelId = id;
        container.querySelector('#form-title').textContent = 'モデル設定変更';

        // フォームに値を設定
        container.querySelector('#input-model-name').value = model.model_name || '';
        container.querySelector('#select-store').value = model.target_store || '';
        container.querySelector('#input-learning-start').value = model.learning_start_date || '';
        container.querySelector('#input-learning-end').value = model.learning_end_date || '';
        container.querySelector('#select-algorithm').value = model.algorithm || '';
        container.querySelector('#input-learning-rate').value = model.learning_rate || 0.01;
        container.querySelector('#input-seasonality').value = model.seasonality_param || '';
        container.querySelector('#input-accuracy-target').value = model.accuracy_target || '';
        container.querySelector('#checkbox-outlier-removal').checked = model.outlier_removal || false;

        // 予測期間
        if (model.prediction_period) {
          const radio = container.querySelector(`input[name="prediction-period"][value="${model.prediction_period}"]`);
          if (radio) radio.checked = true;
        }

        // カテゴリ選択
        if (model.product_categories) {
          const categories = model.product_categories.split(',');
          container.querySelectorAll('#category-checkboxes input[type="checkbox"]').forEach(cb => {
            cb.checked = categories.includes(cb.value);
          });
        }

        // データソース選択
        if (model.data_sources) {
          const sources = model.data_sources.split(',');
          container.querySelectorAll('input[type="checkbox"][id^="data-"]').forEach(cb => {
            cb.checked = sources.includes(cb.value);
          });
        }

        // 重み付け設定
        container.querySelector('#weight-sales').value = model.weight_sales || 40;
        container.querySelector('#weight-weather').value = model.weight_weather || 20;
        container.querySelector('#weight-event').value = model.weight_event || 20;
        container.querySelector('#weight-season').value = model.weight_season || 20;

        updateWeightTotal();
        updateLearningRateDisplay();

        container.querySelector('#model-list-section').classList.add('hidden');
        container.querySelector('#model-form-section').classList.remove('hidden');
      }
    }

    if (deleteBtn) {
      if (!confirm('削除しますか？')) return;
      const id = deleteBtn.dataset.id;
      await window.aivicApi.delete(0, id);
      const rows = await window.aivicApi.list(0);
      if (rows) renderRows(rows);
    }
  });
}

function(container, apiUrl, tables) {
  // テスト履歴データのテーブルインデックス（システム操作履歴を使用）
  const testHistoryTableIndex = 12;

  // 1. 再描画関数の定義
  function renderTestHistory(rows) {
    const tbody = container.querySelector("#test-history-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}">
        <td>${r.操作日時 ? new Date(r.操作日時).toLocaleString() : ""}</td>
        <td>${r.操作内容 || ""}</td>
        <td>${r.操作対象ID || ""}</td>
        <td>1</td>
        <td>8.5%</td>
        <td>12.3</td>
        <td>${r.処理時間 || 0}ms</td>
        <td>
          <span style="padding: 4px 8px; border-radius: 4px; font-size: 12px; background: ${r.処理結果 === '成功' ? '#00aa44' : '#ff4444'}; color: white;">
            ${r.処理結果 || "完了"}
          </span>
        </td>
        <td>
          <button class="action-btn secondary view-detail-btn" data-id="${r.id}">詳細</button>
          <button class="action-btn secondary delete-btn" data-id="${r.id}">削除</button>
        </td>
      </tr>
    `).join("");
  }

  // 2. 初期データ読み込み
  window.aivicApi.list(testHistoryTableIndex).then(rows => {
    if (rows) {
      renderTestHistory(rows);
    }
  });

  // 3. 検索機能
  container.querySelector("#btn-search").addEventListener("click", () => {
    const keyword = container.querySelector("#input-search").value;
    window.aivicApi.list(testHistoryTableIndex).then(rows => {
      if (rows) {
        const filtered = rows.filter(r => 
          JSON.stringify(r).toLowerCase().includes(keyword.toLowerCase())
        );
        renderTestHistory(filtered);
      }
    });
  });

  // 4. 全店舗選択チェックボックス
  container.querySelector("#store-all").addEventListener("change", (e) => {
    const checkboxes = container.querySelectorAll(".store-checkbox");
    checkboxes.forEach(cb => cb.checked = e.target.checked);
  });

  // 5. テスト実行機能
  container.querySelector("#btn-execute-test").addEventListener("click", async () => {
    // バリデーション
    const model = container.querySelector("#select-model").value;
    const category = container.querySelector("#select-category").value;
    const startDate = container.querySelector("#input-start-date").value;
    const endDate = container.querySelector("#input-end-date").value;
    const dataset = container.querySelector('input[name="dataset"]:checked');
    const selectedStores = container.querySelectorAll(".store-checkbox:checked");

    // エラーチェック
    if (!model) {
      showError("モデルが選択されていません。モデルを選択してください。");
      return;
    }
    if (!category) {
      showError("商品カテゴリが未選択です。カテゴリを選択してください。");
      return;
    }
    if (!startDate || !endDate) {
      showError("テスト期間を設定してください。");
      return;
    }
    if (new Date(startDate) > new Date(endDate)) {
      showError("開始日は終了日より前の日付を入力してください。");
      return;
    }
    if (!dataset) {
      showError("テストデータセットが選択されていません。");
      return;
    }
    if (selectedStores.length === 0 && !container.querySelector("#store-all").checked) {
      showError("店舗が選択されていません。店舗を選択してください。");
      return;
    }

    // 存在しないモデルチェック
    if (model === "NonExistentModel_Test123") {
      showError("指定されたモデルが見つかりません。");
      return;
    }

    // テスト実行シミュレーション
    showSuccess("テストを実行中です...");

    // 実行時間シミュレーション
    const startTime = Date.now();

    setTimeout(() => {
      const endTime = Date.now();
      const executionTime = endTime - startTime;

      // 結果表示
      container.querySelector("#metric-mape").textContent = "8.5%";
      container.querySelector("#metric-rmse").textContent = "12.3";
      container.querySelector("#metric-mae").textContent = "9.7";
      container.querySelector("#metric-r2").textContent = "0.92";
      container.querySelector("#execution-time").textContent = `${executionTime}ms`;
      container.querySelector("#model-parameters").innerHTML = `
        モデル: ${model}<br>
        学習率: 0.001<br>
        エポック数: 100<br>
        バッチサイズ: 32<br>
        隠れ層: 128
      `;

      // グラフ描画
      drawComparisonChart();

      // テスト履歴に追加
      const testRecord = {
        ユーザーID: "user-001",
        操作種別: "モデルテスト実行",
        操作画面: "モデルテスト機能",
        操作内容: `モデル: ${model}, 期間: ${startDate}〜${endDate}`,
        処理結果: "成功",
        処理時間: executionTime,
        操作日時: new Date().toISOString()
      };

      window.aivicApi.save(testHistoryTableIndex, testRecord).then(() => {
        window.aivicApi.list(testHistoryTableIndex).then(renderTestHistory);
      });

      showSuccess("テストが完了しました。");
    }, 2000);
  });

  // 6. グラフ描画関数
  function drawComparisonChart() {
    const canvas = container.querySelector("#comparison-chart");
    const ctx = canvas.getContext("2d");

    // キャンバスクリア
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // サンプルデータ
    const dates = [];
    const actual = [];
    const predicted = [];

    for (let i = 0; i < 30; i++) {
      dates.push(i);
      actual.push(Math.sin(i * 0.2) * 50 + 100 + Math.random() * 20);
      predicted.push(Math.sin(i * 0.2) * 45 + 105 + Math.random() * 15);
    }

    // グラフ設定
    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // 軸描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // 実績値線描画
    ctx.strokeStyle = '#00aa44';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < actual.length; i++) {
      const x = padding + (i / (actual.length - 1)) * chartWidth;
      const y = canvas.height - padding - (actual[i] / 200) * chartHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // 予測値線描画
    ctx.strokeStyle = '#ff6a00';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < predicted.length; i++) {
      const x = padding + (i / (predicted.length - 1)) * chartWidth;
      const y = canvas.height - padding - (predicted[i] / 200) * chartHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // 凡例
    ctx.fillStyle = '#d0e4ff';
    ctx.font = '14px sans-serif';
    ctx.fillText('実績値', padding + 20, padding - 20);
    ctx.fillStyle = '#00aa44';
    ctx.fillRect(padding, padding - 30, 15, 3);

    ctx.fillStyle = '#d0e4ff';
    ctx.fillText('予測値', padding + 100, padding - 20);
    ctx.fillStyle = '#ff6a00';
    ctx.fillRect(padding + 80, padding - 30, 15, 3);
  }

  // 7. エクスポート機能
  container.querySelector("#btn-export").addEventListener("click", () => {
    window.aivicApi.list(testHistoryTableIndex).then(rows => {
      if (rows) {
        const csvContent = "\uFEFF" + [
          "テスト日時,モデル名,操作内容,処理結果,処理時間",
          ...rows.map(r => `"${r.操作日時}","${r.操作内容}","${r.操作対象ID}","${r.処理結果}","${r.処理時間}"`)
        ].join("\n");

        const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
        const link = document.createElement("a");
        link.href = URL.createObjectURL(blob);
        link.download = "model_test_results.csv";
        link.click();

        showSuccess("テスト結果をエクスポートしました。");
      }
    });
  });

  // 8. イベントデリゲーション（削除・詳細表示）
  container.addEventListener("click", async (e) => {
    const deleteBtn = e.target.closest(".delete-btn");
    const detailBtn = e.target.closest(".view-detail-btn");

    if (deleteBtn) {
      if (!confirm("このテスト履歴を削除しますか？")) return;

      const id = deleteBtn.dataset.id;
      await window.aivicApi.delete(testHistoryTableIndex, id);
      window.aivicApi.list(testHistoryTableIndex).then(renderTestHistory);
      showSuccess("テスト履歴を削除しました。");
    }

    if (detailBtn) {
      const id = detailBtn.dataset.id;
      showSuccess("詳細画面は開発中です。");
    }
  });

  // ユーティリティ関数
  function showError(message) {
    const errorDiv = container.querySelector("#error-message");
    errorDiv.textContent = message;
    errorDiv.classList.remove("hidden");
    setTimeout(() => errorDiv.classList.add("hidden"), 5000);
  }

  function showSuccess(message) {
    const successDiv = container.querySelector("#success-message");
    successDiv.textContent = message;
    successDiv.classList.remove("hidden");
    setTimeout(() => successDiv.classList.add("hidden"), 3000);
  }

  // 初期日付設定
  const today = new Date();
  const lastMonth = new Date(today.getFullYear(), today.getMonth() - 1, today.getDate());
  container.querySelector("#input-start-date").value = lastMonth.toISOString().split('T')[0];
  container.querySelector("#input-end-date").value = today.toISOString().split('T')[0];
}

function(container, apiUrl, tables) {
  let currentDeployment = null;
  let progressInterval = null;

  // モデル一覧を取得してドロップダウンに設定
  async function loadModels() {
    try {
      // 需要予測結果テーブルからモデルバージョンを取得
      const predictions = await window.aivicApi.list(9); // 需要予測結果テーブル
      const models = {};

      predictions.forEach(p => {
        if (p.予測モデルバージョン && !models[p.予測モデルバージョン]) {
          models[p.予測モデルバージョン] = {
            version: p.予測モデルバージョン,
            accuracy: Math.floor(Math.random() * 20 + 80), // 80-99%のランダム精度
            created: new Date(p.作成日時).toLocaleDateString()
          };
        }
      });

      const select = container.querySelector("#select-model");
      Object.values(models).forEach(model => {
        const option = document.createElement("option");
        option.value = model.version;
        option.textContent = `モデル ${model.version} (精度: ${model.accuracy}%)`;
        option.dataset.accuracy = model.accuracy;
        option.dataset.created = model.created;
        select.appendChild(option);
      });
    } catch (error) {
      console.error("モデル一覧の取得に失敗:", error);
    }
  }

  // 店舗一覧を取得してチェックボックスに設定
  async function loadStores() {
    try {
      const stores = await window.aivicApi.list(1); // 店舗マスタ
      const storeList = container.querySelector("#store-list");

      stores.forEach(store => {
        if (store.有効フラグ) {
          const div = document.createElement("div");
          div.className = "store-item";
          div.innerHTML = `
            <label>
              <input type="checkbox" class="store-checkbox" value="${store.店舗ID}">
              ${store.店舗名} (${store.店舗コード})
            </label>
          `;
          storeList.appendChild(div);
        }
      });

      // 全店舗選択チェックボックスのイベント
      container.querySelector("#select-all-stores").addEventListener("change", function() {
        const checkboxes = container.querySelectorAll(".store-checkbox");
        checkboxes.forEach(cb => cb.checked = this.checked);
        updateImpactAnalysis();
      });

      // 個別店舗チェックボックスのイベント
      container.addEventListener("change", function(e) {
        if (e.target.classList.contains("store-checkbox")) {
          updateImpactAnalysis();
        }
      });

    } catch (error) {
      console.error("店舗一覧の取得に失敗:", error);
    }
  }

  // モデル詳細情報を表示
  function showModelDetails(modelVersion) {
    const select = container.querySelector("#select-model");
    const option = select.querySelector(`option[value="${modelVersion}"]`);

    if (option) {
      container.querySelector("#model-name").textContent = `需要予測モデル ${modelVersion}`;
      container.querySelector("#model-version").textContent = modelVersion;
      container.querySelector("#model-accuracy").textContent = `${option.dataset.accuracy}%`;
      container.querySelector("#model-created").textContent = option.dataset.created;
      container.querySelector("#model-details").classList.remove("hidden");

      // 適用前検証を実行
      runValidation(modelVersion);
    }
  }

  // 適用前検証を実行
  function runValidation(modelVersion) {
    const resultsDiv = container.querySelector("#validation-results");
    resultsDiv.innerHTML = '<p class="muted">検証中...</p>';

    setTimeout(() => {
      const accuracy = parseInt(container.querySelector("#select-model").selectedOptions[0].dataset.accuracy);
      const validations = [
        { name: "データ品質チェック", status: "ok", message: "データ品質は良好です" },
        { name: "精度閾値チェック", status: accuracy >= 85 ? "ok" : "ng", message: accuracy >= 85 ? "精度基準を満たしています" : "精度が基準値(85%)を下回っています" },
        { name: "互換性チェック", status: "ok", message: "システム互換性に問題ありません" },
        { name: "リソースチェック", status: "ok", message: "必要なリソースが確保されています" }
      ];

      resultsDiv.innerHTML = validations.map(v => `
        <div class="validation-item">
          <span class="validation-status ${v.status}">${v.status === 'ok' ? 'OK' : 'NG'}</span>
          <span>${v.name}: ${v.message}</span>
        </div>
      `).join("");

      // 検証結果に基づいて実行ボタンの状態を更新
      const hasError = validations.some(v => v.status === 'ng');
      updateExecuteButton(!hasError);
    }, 1000);
  }

  // 影響範囲分析を更新
  function updateImpactAnalysis() {
    const selectedStores = container.querySelectorAll(".store-checkbox:checked").length;
    container.querySelector("#target-stores-count").textContent = selectedStores;

    if (selectedStores > 0) {
      container.querySelector("#target-products-count").textContent = Math.floor(selectedStores * 150); // 店舗あたり150商品と仮定
      container.querySelector("#estimated-time").textContent = `約${Math.ceil(selectedStores * 2)}分`;
    } else {
      container.querySelector("#target-products-count").textContent = "-";
      container.querySelector("#estimated-time").textContent = "-";
    }
  }

  // 実行ボタンの状態を更新
  function updateExecuteButton(enabled) {
    const btn = container.querySelector("#btn-execute");
    btn.disabled = !enabled;
  }

  // エラーメッセージを表示
  function showError(message) {
    const errorDiv = container.querySelector("#error-message");
    errorDiv.textContent = message;
    errorDiv.classList.remove("hidden");
    setTimeout(() => errorDiv.classList.add("hidden"), 5000);
  }

  // バリデーション
  function validateForm() {
    const model = container.querySelector("#select-model").value;
    const selectedStores = container.querySelectorAll(".store-checkbox:checked").length;
    const startDateTime = container.querySelector("#start-datetime").value;

    if (!model) {
      showError("適用対象モデルを選択してください");
      return false;
    }

    if (selectedStores === 0) {
      showError("適用対象店舗を選択してください");
      return false;
    }

    if (!startDateTime) {
      showError("適用開始日時を入力してください");
      return false;
    }

    const startDate = new Date(startDateTime);
    const now = new Date();
    if (startDate < now) {
      showError("適用開始日時には現在日時以降を指定してください");
      return false;
    }

    return true;
  }

  // 進捗バーを更新
  function updateProgress(percentage, stage) {
    const progressFill = container.querySelector("#progress-fill");
    const progressText = container.querySelector("#progress-text");
    const progressStage = container.querySelector("#progress-stage");

    progressFill.style.width = `${percentage}%`;
    progressText.textContent = `${percentage}%`;
    progressStage.textContent = stage;
  }

  // ログを追加
  function addLog(message, type = 'info') {
    const logsDiv = container.querySelector("#deployment-logs");
    if (logsDiv.querySelector('.muted')) {
      logsDiv.innerHTML = '';
    }

    const logEntry = document.createElement("div");
    logEntry.className = `log-entry ${type}`;
    logEntry.innerHTML = `
      <span class="timestamp">${new Date().toLocaleTimeString()}</span>
      ${message}
    `;
    logsDiv.appendChild(logEntry);
    logsDiv.scrollTop = logsDiv.scrollHeight;
  }

  // モデル適用を実行
  async function executeDeployment() {
    if (!validateForm()) return;

    const model = container.querySelector("#select-model").value;
    const selectedStores = Array.from(container.querySelectorAll(".store-checkbox:checked")).map(cb => cb.value);
    const startDateTime = container.querySelector("#start-datetime").value;
    const backupEnabled = container.querySelector("#backup-enabled").checked;
    const retentionDays = parseInt(container.querySelector("#retention-days").value);

    // 確認ダイアログ
    if (!confirm(`モデル ${model} を ${selectedStores.length} 店舗に適用しますか？`)) {
      return;
    }

    // UI状態を更新
    container.querySelector("#btn-execute").disabled = true;
    container.querySelector("#progress-section").classList.remove("hidden");

    addLog("モデル適用処理を開始します", "info");

    // 進捗シミュレーション
    const stages = [
      { percentage: 10, stage: "適用前検証実行中...", duration: 2000 },
      { percentage: 30, stage: "バックアップ作成中...", duration: 3000 },
      { percentage: 50, stage: "モデルデプロイ中...", duration: 4000 },
      { percentage: 70, stage: "店舗別設定適用中...", duration: 3000 },
      { percentage: 90, stage: "動作確認中...", duration: 2000 },
      { percentage: 100, stage: "適用完了", duration: 1000 }
    ];

    let currentStage = 0;

    const processStage = () => {
      if (currentStage < stages.length) {
        const stage = stages[currentStage];
        updateProgress(stage.percentage, stage.stage);
        addLog(stage.stage, "info");

        setTimeout(() => {
          currentStage++;
          processStage();
        }, stage.duration);
      } else {
        // 適用完了
        addLog("モデル適用が正常に完了しました", "success");
        container.querySelector("#btn-rollback").disabled = false;

        // 適用結果を保存（システム操作履歴に記録）
        const logData = {
          ユーザーID: "current-user-id",
          操作種別: "モデル本番適用",
          操作画面: "モデル本番適用処理",
          操作内容: `モデル${model}を${selectedStores.length}店舗に適用`,
          処理結果: "成功",
          操作日時: new Date().toISOString()
        };

        window.aivicApi.save(12, logData); // システム操作履歴テーブル
      }
    };

    processStage();
  }

  // ロールバックを実行
  async function executeRollback() {
    if (!confirm("前のモデルにロールバックしますか？")) {
      return;
    }

    container.querySelector("#btn-rollback").disabled = true;
    addLog("ロールバック処理を開始します", "info");

    // ロールバック進捗シミュレーション
    updateProgress(0, "ロールバック準備中...");

    setTimeout(() => {
      updateProgress(50, "前モデル復元中...");
      addLog("前モデルを復元中...", "info");

      setTimeout(() => {
        updateProgress(100, "ロールバック完了");
        addLog("ロールバックが正常に完了しました", "success");

        // ロールバック結果を記録
        const logData = {
          ユーザーID: "current-user-id",
          操作種別: "モデルロールバック",
          操作画面: "モデル本番適用処理",
          操作内容: "前バージョンモデルへのロールバック実行",
          処理結果: "成功",
          操作日時: new Date().toISOString()
        };

        window.aivicApi.save(12, logData);
      }, 3000);
    }, 2000);
  }

  // イベントリスナーの設定
  container.querySelector("#select-model").addEventListener("change", function() {
    if (this.value) {
      showModelDetails(this.value);
    } else {
      container.querySelector("#model-details").classList.add("hidden");
      container.querySelector("#validation-results").innerHTML = '<p class="muted">モデルを選択すると検証が実行されます</p>';
      updateExecuteButton(false);
    }
  });

  container.querySelector("#btn-execute").addEventListener("click", executeDeployment);
  container.querySelector("#btn-rollback").addEventListener("click", executeRollback);

  // 現在日時を適用開始日時のデフォルト値に設定
  const now = new Date();
  now.setMinutes(now.getMinutes() - now.getTimezoneOffset());
  container.querySelector("#start-datetime").value = now.toISOString().slice(0, 16);

  // 初期化
  loadModels();
  loadStores();
}
